  constraint tournaments_checkin_check CHECK (((check_in_minutes >= 0) AND (check_in_minutes <= 180))),
  constraint tournaments_format_check CHECK ((format = ANY (ARRAY['single_elim'::text, 'double_elim'::text, 'round_robin'::text, 'swiss'::text, 'league'::text, 'world_cup'::text, 'groups_knockout'::text]))),
  constraint tournaments_max_entries_check CHECK (((max_entries >= 2) AND (max_entries <= 64))),
  constraint tournaments_mode_check CHECK ((mode = ANY (ARRAY['1v1'::text, '2v2'::text, '3v3'::text]))),
  constraint tournaments_prize_gems_check CHECK ((prize_gems >= 0)),
  constraint tournaments_prize_source_check CHECK ((prize_source = ANY (ARRAY['system'::text, 'admin_bank'::text, 'none'::text]))),
  constraint tournaments_status_check CHECK ((status = ANY (ARRAY['registration'::text, 'checkin'::text, 'running'::text, 'finished'::text, 'cancelled'::text]))),
  constraint tournaments_visibility_check CHECK ((visibility = ANY (ARRAY['public'::text, 'invite'::text])))
);
create table public.user_blocks (
  blocker uuid not null,
  blocked uuid not null,
  constraint user_blocks_pkey PRIMARY KEY (blocker, blocked),
  constraint user_blocks_blocked_fkey FOREIGN KEY (blocked) REFERENCES profiles(id) ON DELETE CASCADE,
  constraint user_blocks_blocker_fkey FOREIGN KEY (blocker) REFERENCES profiles(id) ON DELETE CASCADE
);
create table public.user_challenges (
  user_id uuid not null,
  day date not null,
  def_id text not null,
  progress integer not null default 0,
  claimed boolean not null default false,
  constraint user_challenges_pkey PRIMARY KEY (user_id, day, def_id),
  constraint user_challenges_def_id_fkey FOREIGN KEY (def_id) REFERENCES challenge_defs(id),
  constraint user_challenges_user_id_fkey FOREIGN KEY (user_id) REFERENCES profiles(id) ON DELETE CASCADE
);
create table public.xp_events (
  id bigint not null default nextval('xp_events_id_seq'::regclass),
  user_id uuid,
  amount integer not null,
  reason text not null,
  ref uuid,
  created_at timestamp with time zone not null default now(),
  constraint xp_events_pkey PRIMARY KEY (id),
  constraint xp_events_user_id_fkey FOREIGN KEY (user_id) REFERENCES profiles(id) ON DELETE CASCADE
);
