-- ===== INDEXES =====
CREATE UNIQUE INDEX admin_applications_open ON public.admin_applications USING btree (user_id) WHERE (status = ANY (ARRAY['pending'::text, 'approved'::text]));
CREATE INDEX admin_audit_at ON public.admin_audit USING btree (created_at DESC);
CREATE INDEX admin_bank_ledger_admin ON public.admin_bank_ledger USING btree (admin_id, created_at DESC);
CREATE INDEX cm_user ON public.conversation_members USING btree (user_id);
CREATE INDEX follows_followee ON public.follows USING btree (followee);
CREATE INDEX inventory_user ON public.inventory USING btree (user_id);
CREATE INDEX matches_live ON public.matches USING btree (status) WHERE (status = 'live'::text);
CREATE INDEX matches_room ON public.matches USING btree (room_id);
CREATE INDEX matches_team_a_idx ON public.matches USING gin (team_a);
CREATE INDEX matches_team_b_idx ON public.matches USING gin (team_b);
CREATE INDEX msg_conv ON public.messages USING btree (conversation_id, created_at DESC);
CREATE INDEX notifications_user ON public.notifications USING btree (user_id, created_at DESC);
CREATE INDEX profiles_arena ON public.profiles USING btree (arena_points DESC);
CREATE INDEX profiles_lower_name ON public.profiles USING btree (lower(username));
CREATE INDEX profiles_rating ON public.profiles USING btree (rating DESC);
CREATE INDEX room_players_room_role ON public.room_players USING btree (room_id, role);
CREATE INDEX room_players_user_id_idx ON public.room_players USING btree (user_id);
CREATE INDEX rp_last_seen ON public.room_players USING btree (last_seen);
CREATE INDEX rooms_mm_idx ON public.rooms USING btree (kind, mode, status);
CREATE INDEX rooms_public_recent ON public.rooms USING btree (updated_at DESC) WHERE (NOT is_private);
CREATE INDEX rooms_status_kind ON public.rooms USING btree (status, kind, mode, updated_at);
CREATE UNIQUE INDEX tournament_codes_e ON public.tournament_codes USING btree (entry_id) WHERE (kind = 'entry'::text);
CREATE UNIQUE INDEX tournament_codes_t ON public.tournament_codes USING btree (tournament_id) WHERE (kind = 'tournament'::text);
CREATE INDEX tournament_prizes_user ON public.tournament_prizes USING btree (user_id);
CREATE UNIQUE INDEX tournaments_wc_month ON public.tournaments USING btree (month) WHERE (format = 'world_cup'::text);
CREATE INDEX xp_events_user ON public.xp_events USING btree (user_id, created_at DESC);

-- ===== VIEWS =====
create or replace view public.club_list as
 SELECT id,
    name,
    tag,
    emblem,
    description,
    owner,
    join_policy,
    min_level,
    max_members,
    conversation_id,
    created_at,
    (( SELECT count(*) AS count
           FROM club_members m
          WHERE m.club_id = c.id))::integer AS members,
    COALESCE(( SELECT sum(p.trophies * 100 + p.rating) AS sum
           FROM club_members m
             JOIN profiles p ON p.id = m.user_id
          WHERE m.club_id = c.id), 0::bigint)::integer AS power
   FROM clubs c;

create or replace view public.inbox as
 SELECT c.id,
    c.kind,
    c.title,
    c.avatar_url,
    c.club_id,
    c.last_message_at,
    m.role,
    m.muted,
    ( SELECT row_to_json(x.*) AS row_to_json
           FROM ( SELECT ms.body,
                    ms.image_url,
                    ms.sender,
                    ms.created_at
                   FROM messages ms
                  WHERE ms.conversation_id = c.id AND NOT ms.deleted
                  ORDER BY ms.created_at DESC
                 LIMIT 1) x) AS last_message,
    (( SELECT count(*) AS count
           FROM messages ms
          WHERE ms.conversation_id = c.id AND ms.created_at > m.last_read_at AND ms.sender <> auth.uid()))::integer AS unread,
    ( SELECT row_to_json(o.*) AS row_to_json
           FROM ( SELECT p.id,
                    p.username,
                    p.avatar,
                    p.avatar_url,
                    p.online_at
                   FROM conversation_members om
                     JOIN profiles p ON p.id = om.user_id
                  WHERE om.conversation_id = c.id AND om.user_id <> auth.uid()
                 LIMIT 1) o) AS peer,
    (( SELECT count(*) AS count
           FROM conversation_members cm
          WHERE cm.conversation_id = c.id))::integer AS members
   FROM conversations c
     JOIN conversation_members m ON m.conversation_id = c.id AND m.user_id = auth.uid();

create or replace view public.leaderboard as
 SELECT id,
    username,
    avatar,
    level,
    xp,
    rating,
    league,
    wins,
    losses,
    draws,
    trophies,
    rank() OVER (ORDER BY rating DESC, xp DESC) AS rank
   FROM profiles;

create or replace view public.profile_stats as
 SELECT id,
    (( SELECT count(*) AS count
           FROM follows f
          WHERE f.followee = p.id))::integer AS followers,
    (( SELECT count(*) AS count
           FROM follows f
          WHERE f.follower = p.id))::integer AS following
   FROM profiles p;

create or replace view public.public_conversations as
 SELECT id,
    kind,
    title,
    about,
    avatar_url,
    last_message_at,
    (( SELECT count(*) AS count
           FROM conversation_members cm
          WHERE cm.conversation_id = c.id))::integer AS members
   FROM conversations c
  WHERE is_public AND (kind = ANY (ARRAY['group'::text, 'channel'::text]));

create or replace view public.room_list as
 SELECT r.id,
    r.code,
    r.name,
    r.mode,
    r.kind,
    r.tier,
    r.status,
    r.is_private,
    r.ranked,
    r.voice,
    r.settings,
    r.created_at,
    r.host,
    h.username AS host_name,
    h.avatar AS host_avatar,
    h.avatar_url AS host_avatar_url,
    h.level AS host_level,
    h.league AS host_league,
    (( SELECT count(*) AS count
           FROM room_players p
          WHERE p.room_id = r.id AND p.role = 'player'::text))::integer AS players,
    (( SELECT count(*) AS count
           FROM room_players p
          WHERE p.room_id = r.id AND p.role = 'spectator'::text))::integer AS spectators,
    room_size(r.mode) * 2 AS capacity
   FROM rooms r
     JOIN profiles h ON h.id = r.host
  WHERE NOT r.is_private AND r.updated_at > (now() - '02:00:00'::interval);

create or replace view public.standings as
 SELECT id,
    tournament_id,
    captain,
    team_name,
    members,
    seed,
    points,
    played,
    wins,
    draws,
    losses,
    gf,
    ga,
    lb_losses,
    eliminated,
    final_rank,
    rank() OVER (PARTITION BY tournament_id ORDER BY points DESC, (gf - ga) DESC, gf DESC) AS pos
   FROM tournament_entries e;


-- ===== FUNCTIONS =====
CREATE OR REPLACE FUNCTION public._audit(p_actor uuid, p_action text, p_target uuid, p_tid uuid, p_details jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  insert into admin_audit(actor, action, target_user, tournament_id, details) values (p_actor, p_action, p_target, p_tid, coalesce(p_details,'{}')) $function$;

CREATE OR REPLACE FUNCTION public._autoseat(r rooms, uid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int := room_size(r.mode); t smallint; s smallint; begin
  for s in 0..n-1 loop
    for t in 0..1 loop
      if not exists(select 1 from room_players where room_id=r.id and role='player' and team=t and slot=s) then
        update room_players set role='player', team=t, slot=s, ready=false where room_id=r.id and user_id=uid; return; end if;
    end loop;
  end loop;
  update room_players set role='spectator', team=null, slot=null, ready=false where room_id=r.id and user_id=uid;
end $function$;

CREATE OR REPLACE FUNCTION public._bank(p_admin uuid, p_delta integer, p_reason text, p_tid uuid DEFAULT NULL::uuid, p_note text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare b int; begin
  insert into admin_banks(admin_id, balance) values (p_admin, 0) on conflict (admin_id) do nothing;
  select balance into b from admin_banks where admin_id = p_admin for update;
  if b + p_delta < 0 then raise exception 'bank insufficient'; end if;
  update admin_banks set balance = b + p_delta, updated_at = now() where admin_id = p_admin;
  insert into admin_bank_ledger(admin_id, delta, balance_after, reason, tournament_id, actor, note)
    values (p_admin, p_delta, b + p_delta, p_reason, p_tid, auth.uid(), p_note);
  return b + p_delta;
end $function$;

CREATE OR REPLACE FUNCTION public._can_manage(p_tid uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select is_owner() or exists(select 1 from tournaments t where t.id = p_tid and t.created_by = auth.uid() and (is_admin() or t.prize_source = 'none')) $function$;

CREATE OR REPLACE FUNCTION public._ch_club()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin perform _progress(new.user_id,'join_club',1); return new; end $function$;

CREATE OR REPLACE FUNCTION public._ch_clubmatch()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare u uuid; begin
  if new.status='done' and old.status='live' and exists(select 1 from club_challenges where room_id=new.room_id) then
    foreach u in array new.team_a || new.team_b loop perform _progress(u,'play_club_challenge',1); end loop;
  end if; return new; end $function$;

CREATE OR REPLACE FUNCTION public._ch_follow()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin perform _progress(new.follower,'social_follow',1); return new; end $function$;

CREATE OR REPLACE FUNCTION public._ch_message()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin if new.sender is not null then perform _progress(new.sender,'send_message',1); end if; return new; end $function$;

CREATE OR REPLACE FUNCTION public._check_reqs(t tournaments, uid uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare pr profiles; begin
  select * into pr from profiles where id = uid;
  if pr.level < greatest(t.min_level, coalesce((t.requirements->>'min_level')::int, 1)) then raise exception 'level too low'; end if;
  if pr.rating < coalesce((t.requirements->>'min_rating')::int, 0) then raise exception 'rating too low'; end if;
  if pr.rating > coalesce((t.requirements->>'max_rating')::int, 100000) then raise exception 'rating too high'; end if;
  if pr.is_guest and coalesce((t.requirements->>'guests')::boolean, true) = false then raise exception 'guest not allowed'; end if;
end $function$;

CREATE OR REPLACE FUNCTION public._club_add(p_club uuid, p_user uuid, p_role text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare cv uuid; begin
  if (select count(*) from club_members where club_id=p_club) >= (select max_members from clubs where id=p_club) then raise exception 'club full'; end if;
  insert into club_members(club_id,user_id,role) values (p_club,p_user,p_role);
  update profiles set club_id=p_club where id=p_user;
  delete from club_requests where user_id=p_user;
  select conversation_id into cv from clubs where id=p_club;
  if cv is not null then insert into conversation_members(conversation_id,user_id,role) values (cv,p_user,case when p_role='leader' then 'owner' else 'member' end) on conflict do nothing; end if;
end $function$;

CREATE OR REPLACE FUNCTION public._club_role(p_club uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ select role from club_members where club_id=p_club and user_id=auth.uid() $function$;

CREATE OR REPLACE FUNCTION public._code(n integer DEFAULT 6)
 RETURNS text
 LANGUAGE sql
AS $function$
  select string_agg(substr('ABCDEFGHJKLMNPQRSTUVWXYZ23456789', 1 + floor(random()*32)::int, 1), '') from generate_series(1, n) $function$;

CREATE OR REPLACE FUNCTION public._daily_cleanup()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ begin
  delete from xp_events where created_at < now() - interval '180 days';
  delete from rooms where status='waiting' and kind not in ('tournament') and updated_at < now() - interval '6 hours';
end $function$;

CREATE OR REPLACE FUNCTION public._finish_tournament(p_tid uuid, p_winner uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare t tournaments; e record; rk int := 0; u uuid; runner uuid; g int; m record; cnt int; i int; amt int; nwin int; share int; paid int := 0; mem uuid[]; begin
  select * into t from tournaments where id=p_tid for update;
  if t.status in ('finished','cancelled') then return; end if;
  if coalesce(t.v,1) < 2 then
    -- v1 behaviour (unchanged)
    if p_winner is null then
      select id into p_winner from tournament_entries where tournament_id=p_tid order by points desc, (gf-ga) desc, gf desc limit 1;
      for e in select id from tournament_entries where tournament_id=p_tid order by points desc,(gf-ga) desc, gf desc loop
        rk := rk+1; update tournament_entries set final_rank=rk where id=e.id; end loop;
    else update tournament_entries set final_rank=1 where id=p_winner; end if;
    update tournaments set status='finished', winner_entry=p_winner, finished_at=now(), stage=case when format='world_cup' then 'finished' else stage end where id=p_tid;
    g := case when t.format='world_cup' then 500 else least(t.prize_gems,30) end;
    foreach u in array coalesce((select members from tournament_entries where id=p_winner),'{}') loop
      update profiles set trophies=trophies+1, gems=gems+g where id=u; end loop;
    if t.format<>'world_cup' then
      select id into runner from tournament_entries where tournament_id=p_tid and id<>p_winner order by coalesce(final_rank,99), points desc, (gf-ga) desc limit 1;
      if runner is not null then update profiles set gems=gems+(g/3) where id in (select unnest(members) from tournament_entries where id=runner); end if;
    end if;
    return;
  end if;
  -- v2: final ranks
  if p_winner is null then
    select id into p_winner from tournament_entries where tournament_id=p_tid order by points desc, (gf-ga) desc, gf desc, seed limit 1;
    for e in select id from tournament_entries where tournament_id=p_tid order by points desc,(gf-ga) desc, gf desc, seed loop
      rk := rk+1; update tournament_entries set final_rank=rk where id=e.id; end loop;
  else
    update tournament_entries set final_rank=1 where id=p_winner;
    for m in select * from tournament_matches where tournament_id=p_tid and bracket in ('main','winners','final','losers') and status='done' and winner_entry is not null loop
      select count(*) into cnt from tournament_matches where tournament_id=p_tid and bracket=m.bracket and round=m.round;
      if m.bracket in ('main','final') or (m.bracket='winners' and t.format<>'double_elim') then
        update tournament_entries set final_rank = case when m.bracket='final' then 2 else cnt+1 end
          where id = case when m.winner_entry=m.entry_a then m.entry_b else m.entry_a end and final_rank is null;
      elsif m.bracket='losers' and m.next_match is not null and exists(select 1 from tournament_matches f where f.id=m.next_match and f.bracket='final') then
        update tournament_entries set final_rank = 3 where id = case when m.winner_entry=m.entry_a then m.entry_b else m.entry_a end and final_rank is null;
      end if;
    end loop;
  end if;
  update tournaments set status='finished', winner_entry=p_winner, finished_at=now(), stage=case when format='groups_knockout' then 'finished' else stage end where id=p_tid;
  update profiles set trophies=trophies+1 where id = any(coalesce((select members from tournament_entries where id=p_winner),'{}'));
  -- diamond prizes: place i shares prize_pool[i] (split between tied entries, then between team members; remainder to the captain)
  for i in 1..coalesce(jsonb_array_length(t.prize_pool),0) loop
    amt := (t.prize_pool->>(i-1))::int; if amt <= 0 then continue; end if;
    select count(*) into nwin from tournament_entries where tournament_id=p_tid and final_rank=i;
    if nwin = 0 then continue; end if;
    for e in select * from tournament_entries where tournament_id=p_tid and final_rank=i loop
      mem := e.members; share := (amt / nwin) / greatest(array_length(mem,1),1);
      foreach u in array mem loop
        g := share + case when u = e.captain then (amt / nwin) - share*array_length(mem,1) else 0 end;
        if g > 0 then
          update profiles set gems=gems+g where id=u;
          insert into tournament_prizes(tournament_id, entry_id, user_id, place, gems) values (p_tid, e.id, u, i, g);
          perform _notify(u, 'prize', 'جایزه‌ی «' || t.name || '»: ' || g || ' الماس 💎', 'رتبه ' || i, jsonb_build_object('tournament', p_tid));
          paid := paid + g;
        end if;
      end loop;
    end loop;
  end loop;
  if t.prize_source = 'admin_bank' then
    insert into admin_bank_ledger(admin_id, delta, balance_after, reason, tournament_id, actor, note)
      select t.created_by, 0, coalesce((select balance from admin_banks where admin_id=t.created_by),0), 'prize_paid', p_tid, null, paid || ' paid of ' || t.prize_escrow;
    if t.prize_escrow - paid > 0 then perform _bank(t.created_by, t.prize_escrow - paid, 'prize_refund', p_tid, 'باقی‌مانده‌ی جایزه'); end if;
    update tournaments set prize_escrow = 0 where id = p_tid;
  end if;
  perform _notify_entries(p_tid, 'tournament_finished', '«' || t.name || '» تمام شد 🏁', 'قهرمان: ' || coalesce((select team_name from tournament_entries where id=p_winner),'—'));
  perform _audit(null, 'tournament_finish', null, p_tid, jsonb_build_object('winner', p_winner, 'paid', paid));
end $function$;

CREATE OR REPLACE FUNCTION public._gen_code()
 RETURNS text
 LANGUAGE plpgsql
AS $function$
declare c text; begin
  loop c := upper(substr(translate(encode(extensions.gen_random_bytes(6),'base64'),'+/=0OIl1','XYZ23456'),1,6));
    exit when not exists(select 1 from public.rooms where code = c); end loop; return c; end $function$;

CREATE OR REPLACE FUNCTION public._grant(uid uuid, p_xp integer, p_coins integer, p_rating integer, p_result integer, p_goals integer, p_reason text, p_ref uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare nx int; begin
  update profiles set xp = xp + p_xp, coins = coins + p_coins, rating = greatest(0, rating + p_rating),
    wins = wins + (p_result=1)::int, losses = losses + (p_result=-1)::int, draws = draws + (p_result=0 and p_reason like 'match%')::int,
    goals = goals + p_goals
  where id = uid returning xp into nx;
  update profiles set level = level_for_xp(nx), league = league_for_rating(rating) where id = uid;
  if p_xp<>0 then insert into xp_events(user_id,amount,reason,ref) values (uid,p_xp,p_reason,p_ref); end if;
end $function$;

CREATE OR REPLACE FUNCTION public._matchmake(p_mode text, p_kind text, p_tier text)
 RETURNS rooms
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare rid uuid; r rooms; my int; tr arena_tiers; cnt int; begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  if p_mode not in ('1v1','2v2','3v3') then raise exception 'bad mode'; end if;
  perform pg_advisory_xact_lock(hashtext('nexora-mm:'||p_mode||':'||p_kind||':'||coalesce(p_tier,'')));
  perform _sweep_rooms();
  select ro.* into r from rooms ro join room_players p on p.room_id=ro.id and p.user_id=auth.uid()
    where ro.kind=p_kind and ro.mode=p_mode and coalesce(ro.tier,'')=coalesce(p_tier,'') and ro.status in ('waiting','playing') limit 1;
  if r.id is not null then
    update room_players set ready=true, last_seen=now() where room_id=r.id and user_id=auth.uid() and role='player';
    return r;
  end if;
  if exists(select 1 from room_players p join rooms ro on ro.id=p.room_id where p.user_id=auth.uid() and p.role='player' and ro.status='playing') then
    raise exception 'match running';
  end if;
  select case when p_kind='arena' then arena_points else rating end into my from profiles where id=auth.uid();
  select ro.id into rid from rooms ro
  where ro.mode=p_mode and ro.kind=p_kind and coalesce(ro.tier,'')=coalesce(p_tier,'') and ro.status='waiting' and not ro.is_private
    and (select count(*) from room_players p where p.room_id=ro.id and p.role='player') < room_size(ro.mode)*2
    and exists(select 1 from room_players p where p.room_id=ro.id and p.last_seen > now() - interval '30 seconds')
  order by abs(coalesce((select avg(case when p_kind='arena' then pr.arena_points else pr.rating end) from room_players p join profiles pr on pr.id=p.user_id
             where p.room_id=ro.id and p.role='player'), my) - my),
           (select count(*) from room_players p where p.room_id=ro.id and p.role='player') desc, ro.created_at
  limit 1;
  if rid is null then
    if p_kind='duel' then
      select * into tr from arena_tiers where id=p_tier;
      r := create_room(p_mode, tr.name||' · '||p_mode, false, true, true,
             jsonb_build_object('goals',tr.goals,'time',tr.time_s,'turn',15,'field',(floor(random()*29))::int,'ball',0,'tier',tr.id), 'duel');
      update rooms set tier=tr.id where id=r.id returning * into r;
    else
      r := create_room(p_mode, case when p_kind='arena' then 'آرنا '||p_mode else 'مسابقه سریع '||p_mode end, false, true, true,
             '{"goals":3,"time":0,"field":6,"turn":15,"ball":0}'::jsonb, p_kind);
    end if;
  else
    r := join_room(null, rid, false);
  end if;
  update room_players set ready=true, last_seen=now() where room_id=r.id and user_id=auth.uid();
  select count(*) into cnt from room_players where room_id=r.id and role='player' and ready;
  if cnt = room_size(p_mode)*2 then perform _start_match(r.id, false); end if;
  select * into r from rooms where id=r.id;
  return r; end $function$;

CREATE OR REPLACE FUNCTION public._notify(p_user uuid, p_kind text, p_title text, p_body text DEFAULT NULL::text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  insert into notifications(user_id, kind, title, body, data) select p_user, p_kind, p_title, p_body, coalesce(p_data,'{}') where p_user is not null $function$;

CREATE OR REPLACE FUNCTION public._notify_entries(p_tid uuid, p_kind text, p_title text, p_body text, p_status text[] DEFAULT ARRAY['approved'::text])
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  insert into notifications(user_id, kind, title, body, data)
  select distinct u, p_kind, p_title, p_body, jsonb_build_object('tournament', p_tid)
  from tournament_entries e, unnest(e.members) u where e.tournament_id = p_tid and e.status = any(p_status) $function$;

CREATE OR REPLACE FUNCTION public._notify_owners(p_kind text, p_title text, p_body text DEFAULT NULL::text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  insert into notifications(user_id, kind, title, body, data) select id, p_kind, p_title, p_body, coalesce(p_data,'{}') from profiles where role = 'owner' $function$;

CREATE OR REPLACE FUNCTION public._oracle_cfg()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'vault'
AS $function$
  select jsonb_build_object(
    'key', (select decrypted_secret from vault.decrypted_secrets where name = 'nexora_openai_key'),
    'base', (select decrypted_secret from vault.decrypted_secrets where name = 'nexora_openai_base'));
$function$;

CREATE OR REPLACE FUNCTION public._oracle_hit(p_user uuid)
 RETURNS integer
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  insert into oracle_usage(user_id, day, n) values (p_user, (now() at time zone 'Asia/Tehran')::date, 1)
  on conflict (user_id, day) do update set n = oracle_usage.n + 1 returning n $function$;

CREATE OR REPLACE FUNCTION public._oracle_store_cfg(p_key text, p_base text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'vault'
AS $function$
declare kid uuid; bid uuid; begin
  select id into kid from vault.secrets where name = 'nexora_openai_key';
  if kid is null then perform vault.create_secret(p_key, 'nexora_openai_key', 'NEXORA Oracle OpenAI key');
  else perform vault.update_secret(kid, p_key); end if;
  select id into bid from vault.secrets where name = 'nexora_openai_base';
  if bid is null then perform vault.create_secret(p_base, 'nexora_openai_base', 'NEXORA Oracle OpenAI base URL');
  else perform vault.update_secret(bid, p_base); end if;
end $function$;

CREATE OR REPLACE FUNCTION public._pool_sum(p jsonb)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select coalesce(sum((x #>> '{}')::int),0)::int from jsonb_array_elements(coalesce(p,'[]')) x $function$;

CREATE OR REPLACE FUNCTION public._progress(uid uuid, p_kind text, amt integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d date := (now() at time zone 'Asia/Tehran')::date; begin
  if amt <= 0 then return; end if;
  update user_challenges uc set progress = case when p_kind='streak' then greatest(progress, amt) else least(progress + amt, cd.target) end
  from challenge_defs cd where uc.def_id=cd.id and uc.user_id=uid and uc.day=d and cd.kind=p_kind and not uc.claimed;
  update user_challenges uc set progress = least(progress, cd.target) from challenge_defs cd where uc.def_id=cd.id and uc.user_id=uid and uc.day=d;
end $function$;

CREATE OR REPLACE FUNCTION public._refund_stakes(p_match uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare s record; begin
  for s in select * from arena_stakes where match_id=p_match and status='held' for update loop
    if s.currency='gems' then update profiles set gems=gems+s.amount where id=s.user_id;
    else update profiles set coins=coins+s.amount where id=s.user_id; end if;
    update arena_stakes set status='refunded', settled_at=now() where match_id=p_match and user_id=s.user_id;
  end loop; end $function$;

CREATE OR REPLACE FUNCTION public._resolve_byes(p_tid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare m record; changed boolean := true; feeders int; fin int; e uuid; guard int := 0; begin
  while changed and guard < 200 loop
    changed := false; guard := guard+1;
    for m in select * from tournament_matches where tournament_id=p_tid and status='pending' loop
      select count(*), count(*) filter (where status in ('done','bye')) into feeders, fin
        from tournament_matches where next_match=m.id or loser_next=m.id;
      if feeders>0 and feeders=fin and (m.entry_a is null or m.entry_b is null) then
        e := coalesce(m.entry_a, m.entry_b);
        update tournament_matches set status='bye', winner_entry=e where id=m.id;
        if e is not null then perform _tm_place(m.next_match, m.next_slot, e);
          if m.next_match is null then perform _finish_tournament(p_tid, e); end if; end if;
        changed := true;
      end if;
    end loop;
  end loop; end $function$;

CREATE OR REPLACE FUNCTION public._room_default_field()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$ begin
  if new.kind in ('quick','arena') and coalesce(new.settings->>'field','6')='6' then
    new.settings := coalesce(new.settings,'{}'::jsonb) || jsonb_build_object('field',29);
  end if; return new; end $function$;

CREATE OR REPLACE FUNCTION public._rr_schedule(p_tid uuid, ids uuid[], legs integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int; arr uuid[]; rnd int; i int; a uuid; b uuid; leg int; idx int; total_r int; begin
  arr := ids; if array_length(arr,1) % 2 = 1 then arr := arr || array[null::uuid]; end if;
  n := array_length(arr,1); total_r := n-1;
  for leg in 0..legs-1 loop
    for rnd in 0..total_r-1 loop
      idx := 0;
      for i in 0..(n/2)-1 loop
        a := arr[i+1]; b := arr[n-i];
        if a is not null and b is not null then
          if leg % 2 = 1 then insert into tournament_matches(tournament_id,bracket,round,idx,entry_a,entry_b,status) values (p_tid,'main',leg*total_r+rnd+1,idx,b,a,'ready');
          else insert into tournament_matches(tournament_id,bracket,round,idx,entry_a,entry_b,status) values (p_tid,'main',leg*total_r+rnd+1,idx,a,b,'ready'); end if;
          idx := idx+1;
        end if;
      end loop;
      arr := array[arr[1]] || array[arr[n]] || arr[2:n-1];
    end loop;
  end loop; end $function$;

CREATE OR REPLACE FUNCTION public._seed_order(size integer)
 RETURNS integer[]
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare o int[] := array[1,2]; n int := 2; nx int[]; x int; begin
  while n < size loop n := n*2; nx := '{}'; foreach x in array o loop nx := nx || x || (n + 1 - x); end loop; o := nx; end loop;
  return o;
end $function$;

CREATE OR REPLACE FUNCTION public._start_match(p_room uuid, p_bots boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r rooms; n int; a uuid[]; b uuid[]; mid uuid; tm tournament_matches; tr arena_tiers; u uuid; broke uuid[] := '{}'; bal int; is_full boolean; begin
  select * into r from rooms where id=p_room for update;
  if r.id is null then raise exception 'room not found'; end if;
  if r.kind='social' then raise exception 'not allowed'; end if;
  if r.status<>'waiting' then return r.current_match; end if;
  n := room_size(r.mode);
  select coalesce(array_agg(user_id order by slot), '{}') into a from room_players where room_id=p_room and role='player' and team=0;
  select coalesce(array_agg(user_id order by slot), '{}') into b from room_players where room_id=p_room and role='player' and team=1;
  is_full := coalesce(array_length(a,1),0)=n and coalesce(array_length(b,1),0)=n;
  if not is_full then
    -- duels (stakes) and tournament matches always need both sides complete
    if not p_bots or r.kind='duel' or r.tournament_match_id is not null then raise exception 'teams not full'; end if;
    if coalesce(array_length(a,1),0) + coalesce(array_length(b,1),0) = 0 then raise exception 'teams not full'; end if;
  end if;
  if r.kind='duel' then
    select * into tr from arena_tiers where id=r.tier;
    if tr.id is null then raise exception 'bad tier'; end if;
    perform 1 from profiles where id = any(a||b) for update;
    foreach u in array a||b loop
      select case when tr.currency='gems' then gems else coins end into bal from profiles where id=u;
      if coalesce(bal,0) < tr.entry then broke := broke || u; end if;
    end loop;
    if array_length(broke,1) > 0 then
      delete from room_players where room_id=p_room and user_id = any(broke);
      update rooms set updated_at=now() where id=p_room;
      return null;
    end if;
  end if;
  if r.tournament_match_id is not null then select * into tm from tournament_matches where id=r.tournament_match_id; end if;
  insert into matches(room_id,mode,team_a,team_b,ranked,tournament_id,tournament_match_id,bots)
    values (p_room,r.mode,a,b,r.ranked and is_full,tm.tournament_id,r.tournament_match_id,not is_full) returning id into mid;
  if r.kind='duel' then
    foreach u in array a||b loop
      if tr.currency='gems' then update profiles set gems=gems-tr.entry where id=u; else update profiles set coins=coins-tr.entry where id=u; end if;
      insert into arena_stakes(match_id,user_id,tier,currency,amount) values (mid,u,tr.id,tr.currency,tr.entry);
    end loop;
  end if;
  update rooms set status='playing', current_match=mid, updated_at=now() where id=p_room;
  update room_players set last_seen=now() where room_id=p_room;
  if tm.id is not null then update tournament_matches set status='live' where id=tm.id; end if;
  return mid; end $function$;

CREATE OR REPLACE FUNCTION public._sweep_rooms()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r record; nh uuid; m record; begin
  -- 1) silent players (> 45 s without heartbeat) leave waiting rooms
  delete from room_players rp using rooms ro where ro.id=rp.room_id and ro.status='waiting' and rp.last_seen < now() - interval '45 seconds';
  -- 2) matches nobody is heartbeating for (> 90 s) or running > 40 min are abandoned and refunded
  for m in select mt.id, mt.room_id from matches mt where mt.status='live' and (
      mt.started_at < now() - interval '40 minutes'
      or not exists(select 1 from room_players p where p.room_id=mt.room_id and p.last_seen > now() - interval '90 seconds')) loop
    update matches set status='abandoned', ended_at=now() where id=m.id;
    perform _refund_stakes(m.id);
    update tournament_matches set status='ready' where id=(select tournament_match_id from matches where id=m.id) and status='live';
    update rooms set status='waiting', current_match=null, updated_at=now() where id=m.room_id;
    update room_players set ready=false where room_id=m.room_id;
  end loop;
  -- 3) matchmade rooms that never filled within 10 min are closed
  delete from rooms ro where ro.status='waiting' and ro.kind in ('quick','arena','duel') and ro.updated_at < now() - interval '10 minutes';
  -- 4) empty rooms
  delete from rooms ro where not exists(select 1 from room_players p where p.room_id=ro.id);
  -- 5) host left → next player becomes host
  for r in select ro.id from rooms ro where not exists(select 1 from room_players p where p.room_id=ro.id and p.user_id=ro.host) loop
    select user_id into nh from room_players where room_id=r.id order by (role='player') desc, joined_at limit 1;
    update rooms set host=nh, updated_at=now() where id=r.id;
  end loop;
end $function$;

CREATE OR REPLACE FUNCTION public._swiss_round(p_tid uuid, p_round integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare ids uuid[]; i int := 1; idx int := 0; a uuid; b uuid; used uuid[] := '{}'; j int; begin
  select array_agg(id order by points desc, (gf-ga) desc, seed) into ids from tournament_entries where tournament_id=p_tid;
  while i <= array_length(ids,1) loop
    a := ids[i];
    if a = any(used) then i := i+1; continue; end if;
    b := null;
    for j in i+1..array_length(ids,1) loop
      if not ids[j] = any(used) and not exists(select 1 from tournament_matches where tournament_id=p_tid and
         ((entry_a=a and entry_b=ids[j]) or (entry_a=ids[j] and entry_b=a))) then b := ids[j]; exit; end if;
    end loop;
    if b is null then for j in i+1..array_length(ids,1) loop if not ids[j] = any(used) then b := ids[j]; exit; end if; end loop; end if;
    used := used || a;
    if b is null then
      insert into tournament_matches(tournament_id,bracket,round,idx,entry_a,status,winner_entry) values (p_tid,'main',p_round,idx,a,'bye',a);
      update tournament_entries set points=points+3, wins=wins+1, played=played+1 where id=a;
    else used := used || b;
      insert into tournament_matches(tournament_id,bracket,round,idx,entry_a,entry_b,status) values (p_tid,'main',p_round,idx,a,b,'ready'); end if;
    idx := idx+1; i := i+1;
  end loop;
  update tournaments set current_round=p_round where id=p_tid; end $function$;

CREATE OR REPLACE FUNCTION public._sync_owner()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if lower(coalesce(new.email,'')) = owner_email() and new.email_confirmed_at is not null then
    update profiles set role = 'owner' where id = new.id and role <> 'owner';
  end if;
  return new;
end $function$;

CREATE OR REPLACE FUNCTION public._tm_place(p_match uuid, p_slot smallint, p_entry uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare m tournament_matches; begin
  if p_match is null then return; end if;
  if p_slot=0 then update tournament_matches set entry_a=p_entry where id=p_match; else update tournament_matches set entry_b=p_entry where id=p_match; end if;
  update tournament_matches set status='ready', deadline = coalesce(deadline, now() + interval '20 minutes')
    where id=p_match and entry_a is not null and entry_b is not null and status='pending' returning * into m;
  if m.id is not null and exists(select 1 from tournaments where id = m.tournament_id and v = 2) then
    insert into notifications(user_id, kind, title, body, data)
    select u, 'match_ready', 'مسابقه‌ی تورنمنتت آماده است ⚔️', null, jsonb_build_object('tournament', m.tournament_id, 'match', m.id)
    from tournament_entries e, unnest(e.members) u where e.id in (m.entry_a, m.entry_b);
  end if;
end $function$;

CREATE OR REPLACE FUNCTION public._tm_result(p_tm uuid, sa integer, sb integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare tm tournament_matches; t tournaments; win uuid; los uuid; begin
  select * into tm from tournament_matches where id=p_tm for update;
  if tm.status in ('done','bye') then return; end if;
  select * into t from tournaments where id=tm.tournament_id;
  update tournament_matches set score_a=sa, score_b=sb, status='done' where id=p_tm;
  update tournament_entries set played=played+1, gf=gf+sa, ga=ga+sb, wins=wins+(sa>sb)::int, draws=draws+(sa=sb)::int, losses=losses+(sa<sb)::int,
    points=points+case when sa>sb then 3 when sa=sb then 1 else 0 end where id=tm.entry_a;
  update tournament_entries set played=played+1, gf=gf+sb, ga=ga+sa, wins=wins+(sb>sa)::int, draws=draws+(sa=sb)::int, losses=losses+(sb<sa)::int,
    points=points+case when sb>sa then 3 when sa=sb then 1 else 0 end where id=tm.entry_b;
  if tm.bracket='group' then
    update tournament_matches set winner_entry=case when sa>sb then tm.entry_a when sb>sa then tm.entry_b end where id=p_tm;
    if not exists(select 1 from tournament_matches where tournament_id=t.id and bracket='group' and round=tm.round and status in ('pending','ready','live')) then
      update tournaments set current_round=greatest(current_round, tm.round+1) where id=t.id;
    end if;
    if not exists(select 1 from tournament_matches where tournament_id=t.id and bracket='group' and status in ('pending','ready','live')) then
      if t.format = 'groups_knockout' then perform _v6_groups_ko(t.id); else perform _wc_knockout(t.id); end if;
    end if;
    return;
  end if;
  if t.format in ('round_robin','league','swiss') then
    if not exists(select 1 from tournament_matches where tournament_id=t.id and status in ('pending','ready','live')) then
      if t.format='swiss' and t.current_round < t.rounds then perform _swiss_round(t.id, t.current_round+1);
      else perform _finish_tournament(t.id, null); end if;
    end if; return;
  end if;
  if sa>=sb then win:=tm.entry_a; los:=tm.entry_b; else win:=tm.entry_b; los:=tm.entry_a; end if;
  update tournament_matches set winner_entry=win where id=p_tm;
  if tm.bracket='final' then perform _finish_tournament(t.id, win); return; end if;
  if tm.loser_next is not null then perform _tm_place(tm.loser_next, tm.loser_slot, los); perform _resolve_byes(t.id);
  else update tournament_entries set eliminated=true where id=los; end if;
  if tm.next_match is null then perform _finish_tournament(t.id, win); return; end if;
  perform _tm_place(tm.next_match, tm.next_slot, win);
  perform _resolve_byes(t.id);
  update tournaments set current_round=greatest(current_round, tm.round+1) where id=t.id;
end $function$;

CREATE OR REPLACE FUNCTION public._touch_conv()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin update conversations set last_message_at=new.created_at where id=new.conversation_id; return new; end $function$;

CREATE OR REPLACE FUNCTION public._tsize(m text)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
AS $function$ select case m when '2v2' then 2 when '3v3' then 3 else 1 end $function$;

CREATE OR REPLACE FUNCTION public._v6_bracket(p_tid uuid, ids uuid[], p_double boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int := coalesce(array_length(ids,1),0); size int := 2; rounds int; r int; i int; mid uuid; nxt uuid; m record; ord int[]; br text := case when p_double then 'winners' else 'main' end; begin
  while size < n loop size := size*2; end loop;
  rounds := round(ln(size)/ln(2)); ord := _seed_order(size);
  for r in 1..rounds loop for i in 0..(size/(2^r)::int)-1 loop
    insert into tournament_matches(tournament_id,bracket,round,idx) values (p_tid, br, r, i); end loop; end loop;
  for m in select * from tournament_matches where tournament_id=p_tid and bracket=br and round<rounds loop
    select id into nxt from tournament_matches where tournament_id=p_tid and bracket=br and round=m.round+1 and idx=m.idx/2;
    update tournament_matches set next_match=nxt, next_slot=(m.idx%2) where id=m.id;
  end loop;
  if p_double then
    for r in 1..greatest(2*(rounds-1),0) loop for i in 0..greatest((size/(2^(((r+1)/2)+1))::int)-1,0) loop
      insert into tournament_matches(tournament_id,bracket,round,idx) values (p_tid,'losers',r,i); end loop; end loop;
    insert into tournament_matches(tournament_id,bracket,round,idx) values (p_tid,'final',1,0);
    for m in select * from tournament_matches where tournament_id=p_tid and bracket='losers' loop
      if m.round = 2*(rounds-1) then select id into nxt from tournament_matches where tournament_id=p_tid and bracket='final';
        update tournament_matches set next_match=nxt, next_slot=1 where id=m.id;
      elsif m.round % 2 = 1 then select id into nxt from tournament_matches where tournament_id=p_tid and bracket='losers' and round=m.round+1 and idx=m.idx;
        update tournament_matches set next_match=nxt, next_slot=0 where id=m.id;
      else select id into nxt from tournament_matches where tournament_id=p_tid and bracket='losers' and round=m.round+1 and idx=m.idx/2;
        update tournament_matches set next_match=nxt, next_slot=(m.idx%2) where id=m.id; end if;
    end loop;
    for m in select * from tournament_matches where tournament_id=p_tid and bracket='winners' loop
      if m.round=1 then select id into nxt from tournament_matches where tournament_id=p_tid and bracket='losers' and round=1 and idx=m.idx/2;
        update tournament_matches set loser_next=nxt, loser_slot=(m.idx%2) where id=m.id;
      elsif m.round=rounds then select id into nxt from tournament_matches where tournament_id=p_tid and bracket='final';
        update tournament_matches set next_match=nxt, next_slot=0 where id=m.id;
        select id into nxt from tournament_matches where tournament_id=p_tid and bracket='losers' and round=2*(rounds-1);
        update tournament_matches set loser_next=nxt, loser_slot=1 where id=m.id;
      else select id into nxt from tournament_matches where tournament_id=p_tid and bracket='losers' and round=2*(m.round-1) and idx=m.idx;
        update tournament_matches set loser_next=nxt, loser_slot=1 where id=m.id; end if;
    end loop;
  end if;
  for i in 0..size/2-1 loop
    select id into mid from tournament_matches where tournament_id=p_tid and bracket=br and round=1 and idx=i;
    update tournament_matches set entry_a = case when ord[2*i+1] <= n then ids[ord[2*i+1]] end, entry_b = case when ord[2*i+2] <= n then ids[ord[2*i+2]] end where id=mid;
  end loop;
  for m in select * from tournament_matches where tournament_id=p_tid and round=1 and bracket=br loop
    if m.entry_a is not null and m.entry_b is null then update tournament_matches set status='bye', winner_entry=m.entry_a where id=m.id; perform _tm_place(m.next_match, m.next_slot, m.entry_a);
    elsif m.entry_a is null and m.entry_b is not null then update tournament_matches set status='bye', winner_entry=m.entry_b where id=m.id; perform _tm_place(m.next_match, m.next_slot, m.entry_b);
    elsif m.entry_a is not null then update tournament_matches set status='ready' where id=m.id;
    else update tournament_matches set status='bye' where id=m.id; end if;
  end loop;
  perform _resolve_byes(p_tid);
end $function$;

CREATE OR REPLACE FUNCTION public._v6_cancel(p_tid uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare t tournaments; begin
  select * into t from tournaments where id = p_tid for update;
  if t.status in ('finished','cancelled') then return; end if;
  if t.prize_source = 'admin_bank' and t.prize_escrow > 0 then perform _bank(t.created_by, t.prize_escrow, 'prize_refund', t.id, 'لغو تورنمنت'); end if;
  update tournaments set status = 'cancelled', cancelled_reason = p_reason, prize_escrow = 0, finished_at = now() where id = p_tid;
  update tournament_matches set status = 'done' where tournament_id = p_tid and status in ('pending','ready','live');
  perform _notify_entries(p_tid, 'tournament_cancelled', 'تورنمنت «' || t.name || '» لغو شد', p_reason, array['approved','pending']);
end $function$;

CREATE OR REPLACE FUNCTION public._v6_group_rr(p_tid uuid, ids uuid[], g integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare arr uuid[] := ids; n int; rnd int; i int; idx int; begin
  if array_length(arr,1) % 2 = 1 then arr := arr || array[null::uuid]; end if;
  n := array_length(arr,1);
  for rnd in 0..n-2 loop
    idx := 0;
    for i in 0..(n/2)-1 loop
      if arr[i+1] is not null and arr[n-i] is not null then
        insert into tournament_matches(tournament_id,bracket,round,idx,group_no,entry_a,entry_b,status) values (p_tid,'group',rnd+1,g*100+idx,g,arr[i+1],arr[n-i],'ready');
        idx := idx+1; end if;
    end loop;
    arr := array[arr[1]] || array[arr[n]] || arr[2:n-1];
  end loop;
end $function$;

CREATE OR REPLACE FUNCTION public._v6_groups_ko(p_tid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare t tournaments; ng int; adv int; w uuid[]; ru uuid[]; ids uuid[]; g int; i int; e uuid; k int; begin
  select * into t from tournaments where id = p_tid;
  if exists(select 1 from tournament_matches where tournament_id = p_tid and bracket = 'main') then return; end if;
  ng := coalesce(t.groups_count, 1); adv := t.advance_per_group;
  w := array_fill(null::uuid, array[ng]); ru := array_fill(null::uuid, array[ng]);
  for g in 0..ng-1 loop
    i := 0;
    for e in select id from tournament_entries where tournament_id = p_tid and group_no = g order by points desc, (gf-ga) desc, gf desc, seed loop
      if i = 0 then w[g+1] := e; elsif i = 1 and adv = 2 then ru[g+1] := e; else update tournament_entries set eliminated = true where id = e; end if;
      i := i+1;
    end loop;
  end loop;
  if adv = 1 then ids := w;
  else
    k := ng*2; ids := array_fill(null::uuid, array[k]);
    for g in 1..ng loop ids[g] := w[g]; ids[k+1-g] := case when ng = 1 then ru[1] when g % 2 = 1 then ru[g+1] else ru[g-1] end; end loop;
  end if;
  ids := array(select x from unnest(ids) with ordinality u(x, o) where x is not null order by o);
  update tournaments set stage = 'knockout', current_round = 1 where id = p_tid;
  if coalesce(array_length(ids,1),0) < 2 then perform _finish_tournament(p_tid, ids[1]); return; end if;
  perform _v6_bracket(p_tid, ids, false);
  update tournament_matches set deadline = now() + interval '20 minutes' where tournament_id = p_tid and bracket = 'main' and status = 'ready' and deadline is null;
  perform _notify_entries(p_tid, 'stage_knockout', 'مرحله‌ی حذفی «' || t.name || '» شروع شد', null);
end $function$;

CREATE OR REPLACE FUNCTION public._v6_pool(p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare out jsonb := '[]'; x jsonb; v int; begin
  if p is null or jsonb_typeof(p) <> 'array' then return '[]'; end if;
  if jsonb_array_length(p) > 8 then raise exception 'bad prize'; end if;
  for x in select * from jsonb_array_elements(p) loop
    v := (x #>> '{}')::int; if v < 0 or v > 100000 then raise exception 'bad prize'; end if; out := out || to_jsonb(v);
  end loop;
  return out;
end $function$;

CREATE OR REPLACE FUNCTION public._v6_rules(r jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare mi int := coalesce((r->>'minutes')::int, 0); sh int := coalesce((r->>'shots')::int, 0);
  go int := coalesce((r->>'goals')::int, 3); tu int := coalesce((r->>'turn')::int, 15); begin
  if mi < 0 or mi > 30 then raise exception 'bad rules: minutes'; end if;
  if sh < 0 or sh > 99 then raise exception 'bad rules: shots'; end if;
  if go < 0 or go > 15 then raise exception 'bad rules: goals'; end if;
  if tu <> 0 and (tu < 5 or tu > 60) then raise exception 'bad rules: turn'; end if;
  if mi = 0 and sh = 0 and go = 0 then go := 3; end if;
  return jsonb_build_object('minutes', mi, 'shots', sh, 'goals', go, 'turn', tu);
end $function$;

CREATE OR REPLACE FUNCTION public._v6_start(p_tid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare t tournaments; ids uuid[]; n int; ng int; g int; i int; e record; begin
  select * into t from tournaments where id = p_tid for update;
  if t.status not in ('registration','checkin') then return; end if;
  -- no-shows / incomplete teams / unreviewed registrations leave the event before seeding
  for e in select * from tournament_entries where tournament_id = p_tid and status in ('approved','pending') loop
    if e.status = 'pending' then
      perform _notify(u, 'registration_rejected', 'ثبت‌نامت در «' || t.name || '» بررسی نشد', 'تورنمنت شروع شد', jsonb_build_object('tournament', p_tid)) from unnest(e.members) u;
      perform _audit(null, 'auto_remove_pending', e.captain, p_tid, jsonb_build_object('team', e.team_name)); delete from tournament_entries where id = e.id;
    elsif t.check_in_minutes > 0 and coalesce(array_length(e.checked_in,1),0) = 0 then
      perform _notify(u, 'entry_removed', 'به‌خاطر عدم حضور (Check-in) از «' || t.name || '» حذف شدی', null, jsonb_build_object('tournament', p_tid)) from unnest(e.members) u;
      perform _audit(null, 'auto_remove_noshow', e.captain, p_tid, jsonb_build_object('team', e.team_name)); delete from tournament_entries where id = e.id;
    elsif coalesce(array_length(e.members,1),0) < _tsize(t.mode) then
      perform _notify(u, 'entry_removed', 'تیمت در «' || t.name || '» کامل نشد و حذف شد', null, jsonb_build_object('tournament', p_tid)) from unnest(e.members) u;
      perform _audit(null, 'auto_remove_incomplete', e.captain, p_tid, jsonb_build_object('team', e.team_name)); delete from tournament_entries where id = e.id;
    end if;
  end loop;
  delete from tournament_entries where tournament_id = p_tid and status in ('rejected','withdrawn','removed');
  -- automatic seeding: average rating of the team (desc), earliest registration breaks ties
  select array_agg(id order by r desc, created_at) into ids from (
    select te.id, te.created_at, (select coalesce(avg(p.rating),0) from profiles p where p.id = any(te.members)) r from tournament_entries te where te.tournament_id = p_tid) z;
  n := coalesce(array_length(ids,1),0);
  if n < 2 then perform _v6_cancel(p_tid, 'شرکت‌کننده‌ی کافی نبود'); perform _audit(null, 'auto_cancel', null, p_tid, jsonb_build_object('entries', n)); return; end if;
  for i in 1..n loop update tournament_entries set seed = i where id = ids[i]; end loop;
  update tournaments set status = 'running', current_round = 1, stage = case when format = 'groups_knockout' then 'groups' else stage end where id = p_tid;
  if t.format in ('round_robin','league') then perform _rr_schedule(p_tid, ids, case when t.format = 'league' then greatest(coalesce(t.rounds,2),1) else 1 end);
  elsif t.format = 'swiss' then update tournaments set rounds = coalesce(t.rounds, ceil(ln(n)/ln(2))::int) where id = p_tid; perform _swiss_round(p_tid, 1);
  elsif t.format = 'groups_knockout' then
    ng := coalesce(t.groups_count, 2); while ng > 1 and n < ng*2 loop ng := ng/2; end loop;
    update tournaments set groups_count = ng where id = p_tid;
    for i in 1..n loop  -- snake seeding into groups
      g := case when ((i-1)/ng) % 2 = 0 then (i-1) % ng else ng - 1 - (i-1) % ng end;
      update tournament_entries set group_no = g where id = ids[i];
    end loop;
    for g in 0..ng-1 loop perform _v6_group_rr(p_tid, (select array_agg(id order by seed) from tournament_entries where tournament_id = p_tid and group_no = g), g); end loop;
  else perform _v6_bracket(p_tid, ids, t.format = 'double_elim'); end if;
  update tournament_matches set deadline = now() + interval '20 minutes' where tournament_id = p_tid and status = 'ready' and deadline is null;
  perform _notify_entries(p_tid, 'tournament_started', '«' || t.name || '» شروع شد! 🏆', 'مسابقه‌ات را از صفحه‌ی تورنمنت باز کن');
  perform _audit(null, 'tournament_start', null, p_tid, jsonb_build_object('entries', n));
end $function$;

CREATE OR REPLACE FUNCTION public._wc_knockout(p_tid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare ng int; q int; rounds int; r int; i int; m record; nxt uuid; w uuid[]; ru uuid[]; g int; e uuid; mid uuid; begin
  if exists(select 1 from tournament_matches where tournament_id=p_tid and bracket='main') then return; end if;
  select max(group_no)+1 into ng from tournament_entries where tournament_id=p_tid;
  w := array_fill(null::uuid, array[ng]); ru := array_fill(null::uuid, array[ng]);
  for g in 0..ng-1 loop
    i := 0;
    for e in select id from tournament_entries where tournament_id=p_tid and group_no=g order by points desc, (gf-ga) desc, gf desc, seed loop
      if i=0 then w[g+1] := e; elsif i=1 then ru[g+1] := e; else update tournament_entries set eliminated=true where id=e; end if;
      i := i+1;
    end loop;
  end loop;
  q := ng*2; rounds := round(ln(q)/ln(2));
  for r in 1..rounds loop
    for i in 0..(q/(2^r)::int)-1 loop
      insert into tournament_matches(tournament_id,bracket,round,idx,deadline) values (p_tid,'main',r,i, case when r=1 then now()+interval '2 days' end);
    end loop;
  end loop;
  for m in select * from tournament_matches where tournament_id=p_tid and bracket='main' and round<rounds loop
    select id into nxt from tournament_matches where tournament_id=p_tid and bracket='main' and round=m.round+1 and idx=m.idx/2;
    update tournament_matches set next_match=nxt, next_slot=(m.idx%2) where id=m.id;
  end loop;
  -- pairs of groups (2j, 2j+1): winner A vs runner-up B, winner B vs runner-up A
  for i in 0..ng-1 loop
    select id into mid from tournament_matches where tournament_id=p_tid and bracket='main' and round=1 and idx=i;
    if i%2=0 then update tournament_matches set entry_a=w[i+1], entry_b=ru[i+2], status='ready' where id=mid;
    else update tournament_matches set entry_a=w[i+1], entry_b=ru[i], status='ready' where id=mid; end if;
  end loop;
  update tournaments set stage='knockout', current_round=1 where id=p_tid;
end $function$;

CREATE OR REPLACE FUNCTION public._wc_seed(p_tid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare t tournaments; ids uuid[]; n int; size int; ng int; s int; pot int; pos int; g int; grp uuid[]; mid uuid; begin
  select * into t from tournaments where id=p_tid for update;
  if t.status<>'registration' then return; end if;
  -- top of this month's ranking, then (if fewer than 64 played this month) highest rated players
  select array_agg(uid order by ord) into ids from (
    select uid, min(ord) ord from (
      select mr.user_id uid, mr.rank::bigint ord from monthly_ranking(t.month, 64) mr
      union all
      select p.id, 100000 + row_number() over (order by p.rating desc, p.xp desc) from profiles p
    ) z group by uid order by min(ord) limit 64) y;
  n := coalesce(array_length(ids,1),0);
  size := case when n>=64 then 64 when n>=32 then 32 when n>=16 then 16 when n>=8 then 8 else 0 end;
  if size = 0 then update tournaments set starts_at=now()+interval '1 day' where id=p_tid; return; end if;
  ng := size/4;
  for s in 1..size loop
    pot := (s-1)/ng; pos := (s-1)%ng; g := case when pot%2=0 then pos else ng-1-pos end;
    insert into tournament_entries(tournament_id,captain,team_name,members,seed,group_no)
      select p_tid, ids[s], p.username, array[ids[s]], s, g from profiles p where p.id=ids[s];
  end loop;
  for g in 0..ng-1 loop
    select array_agg(id order by seed) into grp from tournament_entries where tournament_id=p_tid and group_no=g;
    insert into tournament_matches(tournament_id,bracket,round,idx,group_no,entry_a,entry_b,status,deadline) values
      (p_tid,'group',1,g*2,g,grp[1],grp[2],'ready',now()+interval '2 days'),(p_tid,'group',1,g*2+1,g,grp[3],grp[4],'ready',now()+interval '2 days'),
      (p_tid,'group',2,g*2,g,grp[1],grp[3],'ready',now()+interval '4 days'),(p_tid,'group',2,g*2+1,g,grp[2],grp[4],'ready',now()+interval '4 days'),
      (p_tid,'group',3,g*2,g,grp[1],grp[4],'ready',now()+interval '6 days'),(p_tid,'group',3,g*2+1,g,grp[2],grp[3],'ready',now()+interval '6 days');
  end loop;
  update tournaments set status='running', stage='groups', current_round=1, max_entries=size where id=p_tid;
end $function$;

CREATE OR REPLACE FUNCTION public.abandon_match(p_match uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare m matches; begin
  select * into m from matches where id=p_match;
  if m.id is null then return; end if;
  if not exists(select 1 from rooms where id=m.room_id and host=auth.uid()) then raise exception 'host only'; end if;
  update matches set status='abandoned', ended_at=now() where id=p_match and status='live';
  if found then
    perform _refund_stakes(p_match);
    update tournament_matches set status='ready' where id=m.tournament_match_id and status='live';
  end if;
  update rooms set status='waiting', current_match=null, updated_at=now() where id=m.room_id and current_match=p_match;
  update room_players set ready=false where room_id=m.room_id; end $function$;

CREATE OR REPLACE FUNCTION public.admin_add_player(p_tid uuid, p_user uuid, p_team_name text DEFAULT NULL::text)
 RETURNS tournament_entries
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare t tournaments; e tournament_entries; nm text; begin
  if not _can_manage(p_tid) then raise exception 'organizer only'; end if;
  select * into t from tournaments where id = p_tid for update;
  if t.id is null then raise exception 'not found'; end if;
  if t.status not in ('registration','checkin') then raise exception 'already started'; end if;
  if exists(select 1 from tournament_entries where tournament_id = p_tid and p_user = any(members) and status in ('pending','approved')) then raise exception 'already joined'; end if;
  if (select count(*) from tournament_entries where tournament_id = p_tid and status = 'approved') >= t.max_entries then raise exception 'full'; end if;
  delete from tournament_entries where tournament_id = p_tid and captain = p_user;
  select username into nm from profiles where id = p_user;
  if nm is null then raise exception 'user not found'; end if;
  if t.prize_source = 'admin_bank' and t.created_by = p_user then raise exception 'organizer cannot play'; end if;
  insert into tournament_entries(tournament_id, captain, team_name, members, status, checked_in)
    values (p_tid, p_user, left(coalesce(nullif(trim(p_team_name),''), nm), 24), array[p_user], 'approved', case when t.status='checkin' then array[p_user] else '{}'::uuid[] end) returning * into e;
  if _tsize(t.mode) > 1 then insert into tournament_codes(code, kind, tournament_id, entry_id) values (_code(6), 'entry', p_tid, e.id); end if;
  perform _notify(p_user, 'tournament_added', 'به تورنمنت «' || t.name || '» اضافه شدی', to_char(t.starts_at at time zone 'Asia/Tehran', 'YYYY-MM-DD HH24:MI') || ' تهران', jsonb_build_object('tournament', p_tid));
  perform _audit(auth.uid(), 'player_add', p_user, p_tid, jsonb_build_object('entry', e.id));
  return e;
end $function$;

CREATE OR REPLACE FUNCTION public.admin_confirm_result(p_tm uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare tm tournament_matches; begin
  select * into tm from tournament_matches where id = p_tm;
  if not _can_manage(tm.tournament_id) then raise exception 'organizer only'; end if;
  if tm.status <> 'done' then raise exception 'not playable'; end if;
  update tournament_matches set confirmed_by = auth.uid() where id = p_tm;
  perform _audit(auth.uid(), 'result_confirm', null, tm.tournament_id, jsonb_build_object('match', p_tm, 'a', tm.score_a, 'b', tm.score_b));
end $function$;

CREATE OR REPLACE FUNCTION public.admin_remove_entry(p_entry uuid, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare e tournament_entries; t tournaments; m record; begin
  select * into e from tournament_entries where id = p_entry for update;
  if e.id is null then raise exception 'not found'; end if;
  if not _can_manage(e.tournament_id) then raise exception 'organizer only'; end if;
  select * into t from tournaments where id = e.tournament_id;
  if t.status in ('registration','checkin') then update tournament_entries set status = 'removed', note = p_reason where id = p_entry;
  elsif t.status = 'running' then
    -- forfeit every playable match (3-0 to the opponent) and eliminate
    for m in select * from tournament_matches where tournament_id = t.id and status in ('ready','live') and (entry_a = p_entry or entry_b = p_entry) order by round loop
      perform _tm_result(m.id, case when m.entry_a = p_entry then 0 else 3 end, case when m.entry_a = p_entry then 3 else 0 end);
    end loop;
    update tournament_entries set eliminated = true, note = coalesce(p_reason, 'حذف توسط ادمین') where id = p_entry;
  else raise exception 'already finished'; end if;
  perform _notify(u, 'entry_removed', 'از «' || t.name || '» حذف شدی', p_reason, jsonb_build_object('tournament', t.id)) from unnest(e.members) u;
  perform _audit(auth.uid(), 'player_remove', e.captain, t.id, jsonb_build_object('entry', p_entry, 'reason', p_reason));
end $function$;

CREATE OR REPLACE FUNCTION public.admin_review_registration(p_entry uuid, p_approve boolean, p_note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare e tournament_entries; t tournaments; n int; begin
  select * into e from tournament_entries where id = p_entry for update;
  if e.id is null then raise exception 'not found'; end if;
  if not _can_manage(e.tournament_id) then raise exception 'organizer only'; end if;
  select * into t from tournaments where id = e.tournament_id;
  if t.status not in ('registration','checkin') then raise exception 'already started'; end if;
  if e.status <> 'pending' and p_approve then return; end if;
  if p_approve then
    select count(*) into n from tournament_entries where tournament_id = t.id and status = 'approved';
    if n >= t.max_entries then raise exception 'full'; end if;
  end if;
  update tournament_entries set status = case when p_approve then 'approved' else 'rejected' end, note = p_note where id = p_entry;
  perform _notify(u, 'registration_' || case when p_approve then 'approved' else 'rejected' end,
    case when p_approve then 'ثبت‌نامت در «' || t.name || '» تأیید شد ✅' else 'ثبت‌نامت در «' || t.name || '» رد شد' end, p_note, jsonb_build_object('tournament', t.id)) from unnest(e.members) u;
  perform _audit(auth.uid(), case when p_approve then 'registration_approve' else 'registration_reject' end, e.captain, t.id, jsonb_build_object('entry', p_entry, 'note', p_note));
end $function$;

CREATE OR REPLACE FUNCTION public.admin_set_result(p_tm uuid, p_sa integer, p_sb integer, p_note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare tm tournament_matches; begin
  select * into tm from tournament_matches where id = p_tm;
  if tm.id is null then raise exception 'not found'; end if;
  if not _can_manage(tm.tournament_id) then raise exception 'organizer only'; end if;
  if tm.status not in ('ready','live') then raise exception 'not playable'; end if;
  if p_sa < 0 or p_sb < 0 or p_sa > 30 or p_sb > 30 then raise exception 'bad score'; end if;
  if not is_owner() and exists(select 1 from tournament_entries e where e.id in (tm.entry_a, tm.entry_b) and auth.uid() = any(e.members)) then raise exception 'own match'; end if;
  perform _tm_result(p_tm, p_sa, p_sb);
  update tournament_matches set result_by = auth.uid(), confirmed_by = auth.uid() where id = p_tm;
  perform _audit(auth.uid(), 'result_set', null, tm.tournament_id, jsonb_build_object('match', p_tm, 'a', p_sa, 'b', p_sb, 'note', p_note));
end $function$;

CREATE OR REPLACE FUNCTION public.admin_start_tournament(p_tid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not _can_manage(p_tid) then raise exception 'organizer only'; end if;
  if not exists(select 1 from tournaments where id = p_tid and status in ('registration','checkin')) then raise exception 'already started'; end if;
  perform _v6_start(p_tid); perform _audit(auth.uid(), 'tournament_start_manual', null, p_tid, '{}');
end $function$;

CREATE OR REPLACE FUNCTION public.apply_admin(p_message text, p_experience text DEFAULT NULL::text, p_contact text DEFAULT NULL::text, p_full_name text DEFAULT NULL::text)
 RETURNS admin_applications
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare a admin_applications; g boolean; begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  select is_guest into g from profiles where id = auth.uid();
  if g then raise exception 'guest not allowed'; end if;
  if is_admin() then raise exception 'already admin'; end if;
  if exists(select 1 from admin_applications where user_id = auth.uid() and status in ('pending','approved')) then raise exception 'application exists'; end if;
  insert into admin_applications(user_id, message, experience, contact, full_name)
    values (auth.uid(), trim(p_message), nullif(trim(p_experience),''), nullif(trim(p_contact),''), nullif(trim(p_full_name),'')) returning * into a;
  perform _audit(auth.uid(), 'admin_apply', auth.uid(), null, jsonb_build_object('application', a.id));
  perform _notify_owners('admin_application', 'درخواست ادمین جدید', (select username from profiles where id = auth.uid()), jsonb_build_object('application', a.id));
  return a;
end $function$;

CREATE OR REPLACE FUNCTION public.buy_disc(p_disc text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d discs; g int; begin
  select * into d from discs where id=p_disc; if d.id is null then raise exception 'disc not found'; end if;
  if exists(select 1 from inventory where user_id=auth.uid() and disc_id=p_disc) then raise exception 'already owned'; end if;
  update profiles set gems = gems - d.price_gems where id=auth.uid() and gems >= d.price_gems returning gems into g;
  if g is null then raise exception 'not enough gems'; end if;
  insert into inventory(user_id,disc_id) values (auth.uid(), p_disc);
  return g; end $function$;

CREATE OR REPLACE FUNCTION public.buy_pack(p_pack text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare pk disc_packs; g int; begin
  select * into pk from disc_packs where id=p_pack; if pk.id is null then raise exception 'pack not found'; end if;
  if not exists(select 1 from unnest(pk.discs) x where not exists(select 1 from inventory i where i.user_id=auth.uid() and i.disc_id=x)) then raise exception 'already owned'; end if;
  update profiles set gems=gems-pk.price_gems where id=auth.uid() and gems>=pk.price_gems returning gems into g;
  if g is null then raise exception 'not enough gems'; end if;
  insert into inventory(user_id,disc_id) select auth.uid(), x from unnest(pk.discs) x on conflict do nothing;
  return g; end $function$;

CREATE OR REPLACE FUNCTION public.can_post(c uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ select exists(select 1 from conversation_members m join conversations v on v.id=m.conversation_id
   where m.conversation_id=c and m.user_id=auth.uid() and (v.kind<>'channel' or m.role in ('owner','admin'))
   and not (v.kind='dm' and exists(select 1 from conversation_members o join user_blocks b on (b.blocker=o.user_id and b.blocked=auth.uid())
     where o.conversation_id=c and o.user_id<>auth.uid()))) $function$;

CREATE OR REPLACE FUNCTION public.cancel_admin_application(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin update admin_applications set status = 'cancelled' where id = p_id and user_id = auth.uid() and status in ('pending','approved'); end $function$;

CREATE OR REPLACE FUNCTION public.cancel_tournament(p_tid uuid, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not _can_manage(p_tid) then raise exception 'organizer only'; end if;
  perform _v6_cancel(p_tid, coalesce(nullif(trim(p_reason),''), 'لغو توسط برگزارکننده'));
  perform _audit(auth.uid(), 'tournament_cancel', null, p_tid, jsonb_build_object('reason', p_reason));
end $function$;

CREATE OR REPLACE FUNCTION public.checkin_tournament(p_tid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare t tournaments; begin
  select * into t from tournaments where id = p_tid;
  if t.check_in_minutes = 0 then raise exception 'no check-in'; end if;
  if now() < t.starts_at - make_interval(mins => t.check_in_minutes) then raise exception 'check-in not open'; end if;
  if t.status not in ('registration','checkin') or now() >= t.starts_at then raise exception 'check-in closed'; end if;
  update tournament_entries set checked_in = array(select distinct x from unnest(checked_in || auth.uid()) x)
    where tournament_id = p_tid and auth.uid() = any(members) and status = 'approved';
  if not found then raise exception 'not registered'; end if;
end $function$;

CREATE OR REPLACE FUNCTION public.claim_challenge(p_def text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d date := (now() at time zone 'Asia/Tehran')::date; uc user_challenges; cd challenge_defs; begin
  select * into uc from user_challenges where user_id=auth.uid() and day=d and def_id=p_def for update;
  select * into cd from challenge_defs where id=p_def;
  if uc.user_id is null then raise exception 'challenge not found'; end if;
  if uc.claimed then raise exception 'already claimed'; end if;
  if uc.progress < cd.target then raise exception 'not completed'; end if;
  update user_challenges set claimed=true where user_id=auth.uid() and day=d and def_id=p_def;
  update profiles set gems=gems+cd.reward_gems where id=auth.uid();
  perform _grant(auth.uid(), cd.reward_xp, 0, 0, 2, 0, 'challenge', null);
  return jsonb_build_object('gems',cd.reward_gems,'xp',cd.reward_xp); end $function$;

CREATE OR REPLACE FUNCTION public.claim_season_reward()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare s seasons; lg text; g int; begin
  select * into s from seasons where ends_at < now() order by ends_at desc limit 1;
  if s.id is null then raise exception 'season running'; end if;
  if exists(select 1 from season_claims where season_id=s.id and user_id=auth.uid()) then raise exception 'already claimed'; end if;
  select league into lg from profiles where id=auth.uid();
  select gems into g from season_rewards where league=lg;
  insert into season_claims values (s.id, auth.uid(), lg, g);
  update profiles set gems=gems+g where id=auth.uid();
  return jsonb_build_object('league',lg,'gems',g); end $function$;

CREATE OR REPLACE FUNCTION public.club_challenge(p_to_club uuid, p_mode text DEFAULT '3v3'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare my club_members; cid uuid; cv uuid; tg text; begin
  select * into my from club_members where user_id=auth.uid();
  if my.club_id is null then raise exception 'club not found'; end if;
  if my.role not in ('leader','officer') then raise exception 'officer only'; end if;
  if p_to_club=my.club_id or not exists(select 1 from clubs where id=p_to_club) then raise exception 'club not found'; end if;
  if exists(select 1 from club_challenges where from_club=my.club_id and to_club=p_to_club and status='pending') then raise exception 'already joined'; end if;
  insert into club_challenges(from_club,to_club,mode,created_by) values (my.club_id,p_to_club,p_mode,auth.uid()) returning id into cid;
  select tag into tg from clubs where id=my.club_id;
  select conversation_id into cv from clubs where id=p_to_club;
  if cv is not null then insert into messages(conversation_id,sender,body) values (cv,null,'⚔️ باشگاه ['||tg||'] شما را به یک چالش '||p_mode||' دعوت کرد. افسران می‌توانند از صفحه‌ی باشگاه بپذیرند.'); end if;
  return cid; end $function$;

CREATE OR REPLACE FUNCTION public.club_challenge_respond(p_id uuid, p_accept boolean)
 RETURNS rooms
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare ch club_challenges; r rooms; ta text; tb text; cv uuid; begin
  select * into ch from club_challenges where id=p_id for update;
  if ch.id is null or ch.status<>'pending' then raise exception 'request not found'; end if;
  if coalesce(_club_role(ch.to_club),'member') not in ('leader','officer') and not (not p_accept and coalesce(_club_role(ch.from_club),'member') in ('leader','officer')) then
    raise exception 'officer only'; end if;
  if not p_accept then
    update club_challenges set status=case when _club_role(ch.from_club) is not null then 'cancelled' else 'declined' end where id=p_id; return null; end if;
  select tag into ta from clubs where id=ch.from_club; select tag into tb from clubs where id=ch.to_club;
  r := create_room(ch.mode, '⚔️ '||ta||' vs '||tb, true, false, true, '{"goals":3,"time":300,"field":6,"turn":15}'::jsonb, 'casual');
  update club_challenges set status='accepted', room_id=r.id, room_code=r.code where id=p_id;
  for cv in select conversation_id from clubs where id in (ch.from_club, ch.to_club) and conversation_id is not null loop
    insert into messages(conversation_id,sender,body) values (cv,null,'⚔️ چالش '||ta||' و '||tb||' پذیرفته شد! کد اتاق: '||r.code);
  end loop;
  return r; end $function$;

CREATE OR REPLACE FUNCTION public.club_decide(p_club uuid, p_user uuid, p_accept boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if coalesce(_club_role(p_club),'member') not in ('leader','officer') then raise exception 'officer only'; end if;
  if not exists(select 1 from club_requests where club_id=p_club and user_id=p_user and kind='request') then raise exception 'request not found'; end if;
  if p_accept then perform _club_add(p_club,p_user,'member'); else delete from club_requests where club_id=p_club and user_id=p_user; end if; end $function$;

CREATE OR REPLACE FUNCTION public.club_invite(p_club uuid, p_user uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if coalesce(_club_role(p_club),'member') not in ('leader','officer') then raise exception 'officer only'; end if;
  insert into club_requests(club_id,user_id,kind) values (p_club,p_user,'invite') on conflict (club_id,user_id) do update set kind='invite'; end $function$;

CREATE OR REPLACE FUNCTION public.club_member_action(p_club uuid, p_user uuid, p_action text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me text := _club_role(p_club); them text; cv uuid; begin
  select role into them from club_members where club_id=p_club and user_id=p_user;
  select conversation_id into cv from clubs where id=p_club;
  if p_action='kick' and me in ('leader','officer') and them='member' or (p_action='kick' and me='leader' and them='officer') then
    delete from club_members where club_id=p_club and user_id=p_user; update profiles set club_id=null where id=p_user;
    delete from conversation_members where conversation_id=cv and user_id=p_user;
  elsif p_action='promote' and me='leader' then update club_members set role='officer' where club_id=p_club and user_id=p_user;
    update conversation_members set role='admin' where conversation_id=cv and user_id=p_user;
  elsif p_action='demote' and me='leader' then update club_members set role='member' where club_id=p_club and user_id=p_user;
    update conversation_members set role='member' where conversation_id=cv and user_id=p_user;
  elsif p_action='transfer' and me='leader' and them is not null then
    update club_members set role='officer' where club_id=p_club and user_id=auth.uid();
    update club_members set role='leader' where club_id=p_club and user_id=p_user; update clubs set owner=p_user where id=p_club;
  else raise exception 'not allowed'; end if; end $function$;

CREATE OR REPLACE FUNCTION public.create_club(p_name text, p_tag text, p_emblem text DEFAULT 'club0'::text, p_desc text DEFAULT NULL::text, p_policy text DEFAULT 'open'::text, p_min_level integer DEFAULT 1)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare cid uuid; cv uuid; begin
  if exists(select 1 from club_members where user_id=auth.uid()) then raise exception 'already in club'; end if;
  update profiles set gems=gems-50 where id=auth.uid() and gems>=50;
  if not found then raise exception 'not enough gems'; end if;
  insert into clubs(name,tag,emblem,description,owner,join_policy,min_level) values (trim(p_name), upper(trim(p_tag)),
    case when exists(select 1 from discs where id=p_emblem) then p_emblem else 'club0' end, p_desc, auth.uid(), p_policy, greatest(p_min_level,1)) returning id into cid;
  insert into conversations(kind,title,owner,club_id) values ('club', trim(p_name), auth.uid(), cid) returning id into cv;
  update clubs set conversation_id=cv where id=cid;
  perform _club_add(cid, auth.uid(), 'leader');
  return cid; end $function$;

CREATE OR REPLACE FUNCTION public.create_conversation(p_kind text, p_title text, p_about text DEFAULT NULL::text, p_public boolean DEFAULT true, p_members uuid[] DEFAULT '{}'::uuid[])
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare cid uuid; u uuid; begin
  if p_kind not in ('group','channel') then raise exception 'bad kind'; end if;
  if char_length(coalesce(trim(p_title),'')) < 2 then raise exception 'title required'; end if;
  insert into conversations(kind,title,about,owner,is_public) values (p_kind,trim(p_title),p_about,auth.uid(),p_public) returning id into cid;
  insert into conversation_members(conversation_id,user_id,role) values (cid,auth.uid(),'owner');
  foreach u in array coalesce(p_members,'{}') loop
    insert into conversation_members(conversation_id,user_id) values (cid,u) on conflict do nothing; end loop;
  return cid; end $function$;

CREATE OR REPLACE FUNCTION public.create_room(p_mode text, p_name text DEFAULT NULL::text, p_private boolean DEFAULT false, p_ranked boolean DEFAULT true, p_voice boolean DEFAULT true, p_settings jsonb DEFAULT NULL::jsonb, p_kind text DEFAULT 'casual'::text)
 RETURNS rooms
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r rooms; begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  if p_kind not in ('casual','social','quick','arena','duel') then raise exception 'bad kind'; end if;
  perform leave_all_rooms();
  insert into rooms(code,name,host,mode,is_private,ranked,voice,settings,kind)
  values (_gen_code(), coalesce(nullif(trim(p_name),''), case when p_kind='social' then 'اتاق گفتگو' else 'اتاق '||p_mode end), auth.uid(), p_mode, p_private,
          p_ranked and p_kind<>'social', p_voice, coalesce(p_settings,'{"goals":3,"time":0,"field":6,"turn":15}'::jsonb), p_kind) returning * into r;
  insert into room_players(room_id,user_id,role,team,slot) values (r.id, auth.uid(),'player',0,0);
  return r; end $function$;

CREATE OR REPLACE FUNCTION public.create_tournament(p_name text, p_format text, p_mode text DEFAULT '1v1'::text, p_max integer DEFAULT 16, p_rounds integer DEFAULT NULL::integer, p_prize_gems integer DEFAULT 20, p_starts timestamp with time zone DEFAULT NULL::timestamp with time zone, p_min_level integer DEFAULT 1)
 RETURNS tournaments
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare t tournaments; begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  if p_format not in ('single_elim','double_elim','round_robin','swiss','league') then raise exception 'bad format'; end if;
  if p_max not in (4,8,16,32,64) then raise exception 'bad size'; end if;
  insert into tournaments(name,format,mode,max_entries,rounds,created_by,prize_xp,prize_coins,prize_gems,starts_at,min_level)
  values (p_name,p_format,p_mode,p_max,p_rounds,auth.uid(),0,0,least(greatest(coalesce(p_prize_gems,20),0),30),p_starts,greatest(p_min_level,1)) returning * into t;
  return t; end $function$;

CREATE OR REPLACE FUNCTION public.create_tournament_v2(p jsonb)
 RETURNS tournaments
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare t tournaments; fmt text := p->>'format'; md text := coalesce(p->>'mode','1v1'); mx int := coalesce((p->>'max_entries')::int, 16);
  st timestamptz := (p->>'starts_at')::timestamptz; pool jsonb := _v6_pool(p->'prize_pool'); total int; src text; adm boolean := is_admin();
  ng int := (p->>'groups_count')::int; adv int := coalesce((p->>'advance_per_group')::int, 2); g boolean; begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  select is_guest into g from profiles where id = auth.uid();
  if fmt not in ('single_elim','double_elim','round_robin','league','groups_knockout','swiss') then raise exception 'bad format'; end if;
  if md not in ('1v1','2v2','3v3') then raise exception 'bad mode'; end if;
  if mx < 2 or mx > 64 then raise exception 'bad size'; end if;
  if char_length(trim(coalesce(p->>'name',''))) < 3 then raise exception 'title required'; end if;
  if st is null or st < now() + interval '2 minutes' or st > now() + interval '60 days' then raise exception 'bad start time'; end if;
  total := _pool_sum(pool);
  if not adm then
    if g then raise exception 'guest not allowed'; end if;
    if total > 0 then raise exception 'admin only'; end if;
    if mx > 16 then raise exception 'bad size'; end if;
    if (select count(*) from tournaments where created_by = auth.uid() and status in ('registration','checkin','running')) >= 3 then raise exception 'too many tournaments'; end if;
    src := 'none';
  else src := case when total = 0 then 'none' when is_owner() then 'system' else 'admin_bank' end; end if;
  if fmt = 'groups_knockout' then
    ng := coalesce(ng, case when mx >= 16 then 4 else 2 end);
    if ng not in (1,2,4,8) or adv not in (1,2) or mx < ng*2 then raise exception 'bad groups'; end if;
  end if;
  insert into tournaments(v,name,description,format,mode,max_entries,rounds,status,created_by,prize_xp,prize_coins,prize_gems,starts_at,min_level,
      rules,style,visibility,check_in_minutes,approval_required,requirements,prize_pool,prize_source,prize_escrow,groups_count,advance_per_group)
  values (2, trim(p->>'name'), nullif(trim(p->>'description'),''), fmt, md, mx,
      case when fmt='league' then greatest(1, least(4, coalesce((p->>'legs')::int, 2))) when fmt='swiss' then (p->>'rounds')::int end,
      'registration', auth.uid(), 0, 0, coalesce((pool->>0)::int, 0), st, greatest(1, coalesce((p#>>'{requirements,min_level}')::int, 1)),
      _v6_rules(p->'rules'), coalesce(p->'style','{}'), coalesce(nullif(p->>'visibility',''),'public'), greatest(0, least(180, coalesce((p->>'check_in_minutes')::int, 0))),
      coalesce((p->>'approval_required')::boolean, false), coalesce(p->'requirements','{}'), pool, src, 0, ng, adv)
  returning * into t;
  insert into tournament_codes(code, kind, tournament_id) values (_code(8), 'tournament', t.id);
  if src = 'admin_bank' then
    perform _bank(auth.uid(), -total, 'prize_escrow', t.id, t.name);
    update tournaments set prize_escrow = total where id = t.id returning * into t;
  end if;
  if adm then perform _audit(auth.uid(), 'tournament_create', null, t.id, jsonb_build_object('name', t.name, 'format', fmt, 'mode', md, 'prize', total, 'source', src)); end if;
  return t;
end $function$;

CREATE OR REPLACE FUNCTION public.current_season()
 RETURNS seasons
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare s seasons; n int; begin
  select * into s from seasons where active order by id desc limit 1;
  if s.ends_at < now() then
    update seasons set active=false where id=s.id;
    select count(*)+1 into n from seasons;
    insert into seasons(name,starts_at,ends_at) values ('فصل '||n, now(), now()+interval '28 days') returning * into s;
  end if;
  return s; end $function$;

CREATE OR REPLACE FUNCTION public.duel_join(p_tier text, p_mode text DEFAULT '1v1'::text)
 RETURNS rooms
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare tr arena_tiers; bal int; begin
  select * into tr from arena_tiers where id=p_tier; if tr.id is null then raise exception 'bad tier'; end if;
  select case when tr.currency='gems' then gems else coins end into bal from profiles where id=auth.uid();
  if coalesce(bal,0) < tr.entry then raise exception '%', case when tr.currency='gems' then 'not enough gems' else 'not enough coins' end; end if;
  return _matchmake(p_mode, 'duel', p_tier); end $function$;

CREATE OR REPLACE FUNCTION public.equip_disc(p_disc text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not exists(select 1 from discs where id=p_disc and price_gems=0) and not exists(select 1 from inventory where user_id=auth.uid() and disc_id=p_disc)
    then raise exception 'not owned'; end if;
  update profiles set equipped_disc=p_disc, avatar=p_disc where id=auth.uid(); end $function$;

CREATE OR REPLACE FUNCTION public.find_tournament_by_code(p_code text)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select tournament_id from tournament_codes where code = upper(trim(coalesce(p_code,''))) and kind = 'tournament' $function$;

CREATE OR REPLACE FUNCTION public.get_daily_challenges()
 RETURNS SETOF user_challenges
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d date := (now() at time zone 'Asia/Tehran')::date; begin
  if not exists(select 1 from user_challenges where user_id=auth.uid() and day=d) then
    insert into user_challenges(user_id,day,def_id)
    select auth.uid(), d, id from (
      select distinct on (kind) id, md5(id || d::text || auth.uid()::text) h from challenge_defs order by kind, md5(id || d::text || auth.uid()::text)
    ) x order by h limit 5;
  end if;
  return query select * from user_challenges where user_id=auth.uid() and day=d order by def_id; end $function$;

CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n text; begin
  n := coalesce(nullif(new.raw_user_meta_data->>'username',''), 'Pilot' || lpad((floor(random()*99999))::text,5,'0'));
  while exists(select 1 from profiles where username = n) loop n := 'Pilot' || lpad((floor(random()*99999))::text,5,'0'); end loop;
  insert into profiles(id, username, is_guest) values (new.id, n, coalesce(new.is_anonymous, false));
  return new;
end $function$;

CREATE OR REPLACE FUNCTION public.handle_user_upgrade()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin update profiles set is_guest = coalesce(new.is_anonymous,false) where id = new.id; return new; end $function$;

CREATE OR REPLACE FUNCTION public.heartbeat(p_room uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin update room_players set last_seen=now() where room_id=p_room and user_id=auth.uid();
  update profiles set online_at=now() where id=auth.uid(); end $function$;

CREATE OR REPLACE FUNCTION public.invite_to_tournament(p_tid uuid, p_user uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare t tournaments; code text; nm text; begin
  select * into t from tournaments where id = p_tid;
  if t.status not in ('registration','checkin') then raise exception 'registration closed'; end if;
  if not (_can_manage(p_tid) or exists(select 1 from tournament_entries where tournament_id = p_tid and auth.uid() = any(members) and status in ('pending','approved'))) then raise exception 'not allowed'; end if;
  if (select count(*) from notifications where kind = 'tournament_invite' and data->>'from' = auth.uid()::text and created_at > now() - interval '1 hour') >= 40 then raise exception 'rate limit'; end if;
  if exists(select 1 from user_blocks where blocker = p_user and blocked = auth.uid()) then raise exception 'blocked'; end if;
  select tc.code into code from tournament_codes tc where tc.tournament_id = p_tid and tc.kind = 'tournament';
  select username into nm from profiles where id = auth.uid();
  perform _notify(p_user, 'tournament_invite', nm || ' تو را به «' || t.name || '» دعوت کرد', to_char(t.starts_at at time zone 'Asia/Tehran', 'YYYY-MM-DD HH24:MI') || ' تهران',
    jsonb_build_object('tournament', p_tid, 'from', auth.uid(), 'code', case when t.visibility = 'invite' then code end));
end $function$;

CREATE OR REPLACE FUNCTION public.is_admin(uid uuid DEFAULT auth.uid())
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select is_owner(uid) or exists(select 1 from admins where user_id = uid and status = 'active') $function$;

CREATE OR REPLACE FUNCTION public.is_member(c uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ select exists(select 1 from conversation_members where conversation_id=c and user_id=auth.uid()) $function$;

CREATE OR REPLACE FUNCTION public.is_owner(uid uuid DEFAULT auth.uid())
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists(select 1 from profiles where id = uid and role = 'owner') $function$;

CREATE OR REPLACE FUNCTION public.join_club(p_club uuid, p_message text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare c clubs; lvl int; begin
  select * into c from clubs where id=p_club; if c.id is null then raise exception 'club not found'; end if;
  if exists(select 1 from club_members where user_id=auth.uid()) then raise exception 'already in club'; end if;
  select level into lvl from profiles where id=auth.uid(); if lvl < c.min_level then raise exception 'level too low'; end if;
  if exists(select 1 from club_requests where club_id=p_club and user_id=auth.uid() and kind='invite') or c.join_policy='open' then
    perform _club_add(p_club, auth.uid(), 'member'); return 'joined'; end if;
  if c.join_policy='invite' then raise exception 'invite only'; end if;
  insert into club_requests(club_id,user_id,kind,message) values (p_club,auth.uid(),'request',p_message) on conflict (club_id,user_id) do update set message=excluded.message, created_at=now();
  return 'requested'; end $function$;

CREATE OR REPLACE FUNCTION public.join_conversation(p_conv uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not exists(select 1 from conversations where id=p_conv and is_public and kind in ('group','channel')) then raise exception 'not public'; end if;
  insert into conversation_members(conversation_id,user_id) values (p_conv,auth.uid()) on conflict do nothing; end $function$;

CREATE OR REPLACE FUNCTION public.join_room(p_code text DEFAULT NULL::text, p_room uuid DEFAULT NULL::uuid, p_spectate boolean DEFAULT false)
 RETURNS rooms
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r rooms; begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  select * into r from rooms where (p_room is not null and id=p_room) or (p_code is not null and code=upper(trim(p_code))) limit 1;
  if r.id is null then raise exception 'room not found'; end if;
  if r.status='finished' then raise exception 'room closed'; end if;
  if exists(select 1 from room_players where room_id=r.id and user_id=auth.uid()) then return r; end if;
  perform leave_all_rooms();
  insert into room_players(room_id,user_id,role) values (r.id, auth.uid(),'spectator');
  if not p_spectate and r.status='waiting' then perform _autoseat(r, auth.uid()); end if;
  update rooms set updated_at=now() where id=r.id;
  return r; end $function$;

CREATE OR REPLACE FUNCTION public.join_team_entry(p_code text)
 RETURNS tournament_entries
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare c tournament_codes; e tournament_entries; t tournaments; begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  select * into c from tournament_codes where code = upper(trim(coalesce(p_code,''))) and kind = 'entry';
  if c.code is null then raise exception 'invalid code'; end if;
  select * into e from tournament_entries where id = c.entry_id for update;
  select * into t from tournaments where id = e.tournament_id;
  if t.status not in ('registration','checkin') or now() >= t.starts_at then raise exception 'registration closed'; end if;
  if e.status not in ('pending','approved') then raise exception 'not found'; end if;
  if auth.uid() = any(e.members) then return e; end if;
  if exists(select 1 from tournament_entries where tournament_id = t.id and auth.uid() = any(members) and status in ('pending','approved')) then raise exception 'already joined'; end if;
  if coalesce(array_length(e.members,1),0) >= _tsize(t.mode) then raise exception 'team full'; end if;
  if t.prize_source = 'admin_bank' and t.created_by = auth.uid() then raise exception 'organizer cannot play'; end if;
  perform _check_reqs(t, auth.uid());
  update tournament_entries set members = members || auth.uid(), checked_in = case when t.status = 'checkin' then checked_in || auth.uid() else checked_in end
    where id = e.id returning * into e;
  perform _notify(e.captain, 'team_join', 'هم‌تیمی جدید', (select username from profiles where id = auth.uid()) || ' به تیم «' || e.team_name || '» پیوست', jsonb_build_object('tournament', t.id));
  return e;
end $function$;

CREATE OR REPLACE FUNCTION public.join_tournament(p_tid uuid, p_team_name text DEFAULT NULL::text, p_members uuid[] DEFAULT NULL::uuid[])
 RETURNS tournament_entries
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare t tournaments; e tournament_entries; nm text; lvl int; begin
  select * into t from tournaments where id=p_tid;
  if t.status<>'registration' then raise exception 'registration closed'; end if;
  if (select count(*) from tournament_entries where tournament_id=p_tid) >= t.max_entries then raise exception 'full'; end if;
  select username, level into nm, lvl from profiles where id=auth.uid();
  if lvl < t.min_level then raise exception 'level too low'; end if;
  if exists(select 1 from tournament_entries where tournament_id=p_tid and auth.uid() = any(members)) then raise exception 'already joined'; end if;
  insert into tournament_entries(tournament_id,captain,team_name,members)
  values (p_tid, auth.uid(), coalesce(nullif(trim(p_team_name),''), nm),
          case when p_members is null then array[auth.uid()] else array(select distinct x from unnest(array[auth.uid()] || p_members) x) end) returning * into e;
  return e; end $function$;

CREATE OR REPLACE FUNCTION public.kick(p_room uuid, p_user uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin if not exists(select 1 from rooms where id=p_room and host=auth.uid()) then raise exception 'host only'; end if;
  delete from room_players where room_id=p_room and user_id=p_user and p_user<>auth.uid(); end $function$;

CREATE OR REPLACE FUNCTION public.league_for_rating(r integer)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$ select id from public.leagues where min_rating <= r order by min_rating desc limit 1 $function$;

CREATE OR REPLACE FUNCTION public.leave_all_rooms()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r record; begin
  for r in select rp.room_id from room_players rp where rp.user_id = auth.uid() loop
    perform public.leave_room(r.room_id);
  end loop; end $function$;

CREATE OR REPLACE FUNCTION public.leave_club()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare cm club_members; nxt uuid; cv uuid; begin
  select * into cm from club_members where user_id=auth.uid(); if cm.club_id is null then return; end if;
  select conversation_id into cv from clubs where id=cm.club_id;
  delete from club_members where user_id=auth.uid(); update profiles set club_id=null where id=auth.uid();
  delete from conversation_members where conversation_id=cv and user_id=auth.uid();
  if not exists(select 1 from club_members where club_id=cm.club_id) then delete from conversations where id=cv; delete from clubs where id=cm.club_id; return; end if;
  if cm.role='leader' then
    select user_id into nxt from club_members where club_id=cm.club_id order by (role='officer') desc, joined_at limit 1;
    update club_members set role='leader' where club_id=cm.club_id and user_id=nxt; update clubs set owner=nxt where id=cm.club_id;
  end if; end $function$;

CREATE OR REPLACE FUNCTION public.leave_conversation(p_conv uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare nxt uuid; begin
  delete from conversation_members where conversation_id=p_conv and user_id=auth.uid();
  if not exists(select 1 from conversation_members where conversation_id=p_conv) then delete from conversations where id=p_conv and kind<>'club'; return; end if;
  if not exists(select 1 from conversation_members where conversation_id=p_conv and role='owner') then
    select user_id into nxt from conversation_members where conversation_id=p_conv order by (role='admin') desc, joined_at limit 1;
    update conversation_members set role='owner' where conversation_id=p_conv and user_id=nxt;
    update conversations set owner=nxt where id=p_conv;
  end if; end $function$;

CREATE OR REPLACE FUNCTION public.leave_room(p_room uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r rooms; nh uuid; begin
  delete from room_players where room_id=p_room and user_id=auth.uid();
  select * into r from rooms where id=p_room; if r.id is null then return; end if;
  if not exists(select 1 from room_players where room_id=p_room) then delete from rooms where id=p_room; return; end if;
  if r.host = auth.uid() then
    select user_id into nh from room_players where room_id=p_room order by (role='player') desc, joined_at limit 1;
    update rooms set host=nh, updated_at=now() where id=p_room;
  else update rooms set updated_at=now() where id=p_room; end if;
end $function$;

CREATE OR REPLACE FUNCTION public.leave_tournament(p_tid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin delete from tournament_entries where tournament_id=p_tid and captain=auth.uid()
  and exists(select 1 from tournaments where id=p_tid and status='registration'); end $function$;

CREATE OR REPLACE FUNCTION public.leave_tournament_v2(p_tid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare e tournament_entries; t tournaments; begin
  select * into t from tournaments where id = p_tid;
  if t.status not in ('registration','checkin') then raise exception 'already started'; end if;
  select * into e from tournament_entries where tournament_id = p_tid and auth.uid() = any(members) and status in ('pending','approved') for update;
  if e.id is null then return; end if;
  if e.captain = auth.uid() then update tournament_entries set status = 'withdrawn' where id = e.id;
    perform _notify(u, 'team_withdrawn', 'تیمت از «' || t.name || '» انصراف داد', null, jsonb_build_object('tournament', p_tid)) from unnest(e.members) u where u <> auth.uid();
  else update tournament_entries set members = array_remove(members, auth.uid()), checked_in = array_remove(checked_in, auth.uid()) where id = e.id; end if;
end $function$;

CREATE OR REPLACE FUNCTION public.level_for_xp(x integer)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
AS $function$ select greatest(1, floor(sqrt(greatest(x,0)/100.0))::int + 1) $function$;

CREATE OR REPLACE FUNCTION public.manage_member(p_conv uuid, p_user uuid, p_action text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare myrole text; begin
  select role into myrole from conversation_members where conversation_id=p_conv and user_id=auth.uid();
  if myrole not in ('owner','admin') then raise exception 'admin only'; end if;
  if p_action='add' then insert into conversation_members(conversation_id,user_id) values (p_conv,p_user) on conflict do nothing;
  elsif p_action='remove' then delete from conversation_members where conversation_id=p_conv and user_id=p_user and role<>'owner';
  elsif p_action='promote' and myrole='owner' then update conversation_members set role='admin' where conversation_id=p_conv and user_id=p_user;
  elsif p_action='demote' and myrole='owner' then update conversation_members set role='member' where conversation_id=p_conv and user_id=p_user and role='admin';
  else raise exception 'bad action'; end if; end $function$;

CREATE OR REPLACE FUNCTION public.mark_notifications_read(p_ids bigint[] DEFAULT NULL::bigint[])
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  update notifications set read = true where user_id = auth.uid() and not read and (p_ids is null or id = any(p_ids)) $function$;

CREATE OR REPLACE FUNCTION public.monthly_ranking(p_month date DEFAULT NULL::date, p_limit integer DEFAULT 100)
 RETURNS TABLE(user_id uuid, username text, avatar text, avatar_url text, level integer, rating integer, points integer, wins integer, draws integer, losses integer, played integer, gd integer, rank integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with mon as (select coalesce(p_month, date_trunc('month', now() at time zone 'Asia/Tehran')::date) m),
  rows as (
    select x as uid, case when mt.winner=0 then 1 when mt.winner=1 then -1 else 0 end res, mt.score_a - mt.score_b diff
      from matches mt, unnest(mt.team_a) x, mon where mt.status='done' and (mt.ended_at at time zone 'Asia/Tehran')::date >= mon.m and (mt.ended_at at time zone 'Asia/Tehran')::date < (mon.m + interval '1 month')::date
    union all
    select x, case when mt.winner=1 then 1 when mt.winner=0 then -1 else 0 end, mt.score_b - mt.score_a
      from matches mt, unnest(mt.team_b) x, mon where mt.status='done' and (mt.ended_at at time zone 'Asia/Tehran')::date >= mon.m and (mt.ended_at at time zone 'Asia/Tehran')::date < (mon.m + interval '1 month')::date
  ), agg as (
    select uid, sum(case res when 1 then 3 when 0 then 1 else 0 end)::int pts, count(*) filter (where res=1)::int w, count(*) filter (where res=0)::int dr,
      count(*) filter (where res=-1)::int l, count(*)::int pl, sum(diff)::int gd from rows group by uid
  )
  select p.id, p.username, p.avatar, p.avatar_url, p.level, p.rating, a.pts, a.w, a.dr, a.l, a.pl, a.gd,
    (rank() over (order by a.pts desc, a.w desc, a.gd desc, p.rating desc))::int
  from agg a join profiles p on p.id=a.uid order by 13 limit greatest(1, least(p_limit, 500));
$function$;

CREATE OR REPLACE FUNCTION public.my_admin()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object(
    'role', (select role from profiles where id = auth.uid()),
    'is_owner', is_owner(), 'is_admin', is_admin(),
    'status', (select status from admins where user_id = auth.uid()),
    'bank', (select balance from admin_banks where admin_id = auth.uid()),
    'application', (select to_jsonb(a) from admin_applications a where user_id = auth.uid() order by created_at desc limit 1)) $function$;

CREATE OR REPLACE FUNCTION public.open_dm(p_user uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare k text; cid uuid; begin
  if p_user = auth.uid() then raise exception 'cannot dm yourself'; end if;
  if exists(select 1 from user_blocks where blocker=p_user and blocked=auth.uid()) then raise exception 'blocked'; end if;
  k := least(auth.uid()::text, p_user::text) || ':' || greatest(auth.uid()::text, p_user::text);
  select id into cid from conversations where dm_key=k;
  if cid is null then
    insert into conversations(kind, dm_key, owner) values ('dm', k, auth.uid()) returning id into cid;
    insert into conversation_members(conversation_id,user_id,role) values (cid,auth.uid(),'member'),(cid,p_user,'member');
  end if;
  return cid; end $function$;

CREATE OR REPLACE FUNCTION public.open_tournament_room(p_tm uuid)
 RETURNS rooms
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare tm tournament_matches; t tournaments; r rooms; ea tournament_entries; eb tournament_entries; side smallint; st jsonb; sl int; begin
  select * into tm from tournament_matches where id=p_tm;
  select * into t from tournaments where id=tm.tournament_id;
  select * into ea from tournament_entries where id=tm.entry_a; select * into eb from tournament_entries where id=tm.entry_b;
  if auth.uid() = any(ea.members) then side:=0; elsif auth.uid() = any(eb.members) then side:=1; else raise exception 'not in this match'; end if;
  if tm.status not in ('ready','live') then raise exception 'match not ready'; end if;
  if tm.room_id is not null and exists(select 1 from rooms where id=tm.room_id and status<>'finished') then
    r := join_room(null, tm.room_id, false);
  else
    st := case when coalesce(t.v,1) >= 2 then jsonb_build_object('goals', greatest(1, coalesce((t.rules->>'goals')::int,3)), 'win', coalesce((t.rules->>'goals')::int,3),
            'time', coalesce((t.rules->>'minutes')::int,0)*60, 'turn', coalesce((t.rules->>'turn')::int,15), 'shots', coalesce((t.rules->>'shots')::int,0), 'field', 0, 'formations', true) end;
    r := create_room(t.mode, left(t.name||' · '||ea.team_name||' vs '||eb.team_name, 60), true, true, true, st);
    update rooms set tournament_match_id=p_tm, kind='tournament' where id=r.id;
    update tournament_matches set room_id=r.id where id=p_tm;
  end if;
  -- seat on our side (first free slot) whatever _autoseat picked
  select coalesce(min(s), -1) into sl from generate_series(0, _tsize(t.mode)-1) s
    where not exists(select 1 from room_players where room_id=r.id and role='player' and team=side and slot=s and user_id<>auth.uid());
  if sl >= 0 then update room_players set role='player', team=side, slot=sl, ready=false where room_id=r.id and user_id=auth.uid()
    and (team is distinct from side or role<>'player'); end if;
  select * into r from rooms where id=r.id; return r;
end $function$;

CREATE OR REPLACE FUNCTION public.organizer_profile(p_user uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object(
    'id', p.id, 'username', p.username, 'avatar', p.avatar, 'avatar_url', p.avatar_url, 'bio', p.bio, 'level', p.level, 'rating', p.rating, 'league', p.league,
    'role', p.role, 'is_admin', is_admin(p.id), 'is_owner', p.role = 'owner',
    'admin_status', (select status from admins where user_id = p.id), 'admin_since', (select granted_at from admins where user_id = p.id),
    'bank', case when auth.uid() = p.id or is_owner() then (select balance from admin_banks where admin_id = p.id) end,
    'followers', (select count(*) from follows where followee = p.id), 'following', (select count(*) from follows where follower = p.id),
    'i_follow', exists(select 1 from follows where follower = auth.uid() and followee = p.id),
    'organized', jsonb_build_object(
      'total', (select count(*) from tournaments where created_by = p.id),
      'players', (select coalesce(sum(coalesce(array_length(e.members,1),0)),0) from tournament_entries e join tournaments t on t.id = e.tournament_id where t.created_by = p.id and e.status = 'approved'),
      'prizes', (select coalesce(sum(x.gems),0) from tournament_prizes x join tournaments t on t.id = x.tournament_id where t.created_by = p.id)),
    'tournaments', (select coalesce(jsonb_agg(z order by z->>'sort' desc), '[]') from (
        select jsonb_build_object('id', t.id, 'name', t.name, 'status', t.status, 'format', t.format, 'mode', t.mode, 'starts_at', t.starts_at, 'max_entries', t.max_entries,
          'prize', _pool_sum(t.prize_pool) + case when t.v < 2 then t.prize_gems else 0 end, 'style', t.style,
          'entries', (select count(*) from tournament_entries e where e.tournament_id = t.id and e.status = 'approved'),
          'winner', (select team_name from tournament_entries e where e.id = t.winner_entry), 'sort', coalesce(t.starts_at, t.created_at)) z
        from tournaments t where t.created_by = p.id order by coalesce(t.starts_at, t.created_at) desc limit 60) q),
    'history', player_tournament_history(p.id))
  from profiles p where p.id = p_user $function$;

CREATE OR REPLACE FUNCTION public.owner_bank_adjust(p_admin uuid, p_delta integer, p_note text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare b int; begin
  if not is_owner() then raise exception 'owner only'; end if;
  if not exists(select 1 from admins where user_id = p_admin) then raise exception 'not admin'; end if;
  if p_delta = 0 or abs(p_delta) > 100000 then raise exception 'bad amount'; end if;
  b := _bank(p_admin, p_delta, 'owner_adjust', null, p_note);
  perform _audit(auth.uid(), 'bank_adjust', p_admin, null, jsonb_build_object('delta', p_delta, 'note', p_note, 'balance', b));
  return b;
end $function$;

CREATE OR REPLACE FUNCTION public.owner_dashboard()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not is_owner() then raise exception 'owner only'; end if;
  return jsonb_build_object(
    'pending', (select count(*) from admin_applications where status = 'pending'),
    'approved_waiting_code', (select count(*) from admin_applications where status = 'approved'),
    'admins', (select count(*) from admins where status = 'active'),
    'suspended', (select count(*) from admins where status = 'suspended'),
    'codes_left', (select count(*) from admin_codes where used_by is null and not revoked),
    'banks_total', (select coalesce(sum(balance),0) from admin_banks),
    'admin_list', (select coalesce(jsonb_agg(jsonb_build_object('user_id', a.user_id, 'status', a.status, 'granted_at', a.granted_at, 'username', p.username,
        'avatar', p.avatar, 'avatar_url', p.avatar_url, 'bank', coalesce(b.balance,0),
        'tournaments', (select count(*) from tournaments t where t.created_by = a.user_id)) order by a.granted_at desc), '[]')
      from admins a join profiles p on p.id = a.user_id left join admin_banks b on b.admin_id = a.user_id where a.status <> 'removed'));
end $function$;

CREATE OR REPLACE FUNCTION public.owner_email()
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$ select 'ashkan.shams132@gmail.com'::text $function$;

CREATE OR REPLACE FUNCTION public.owner_review_application(p_id uuid, p_approve boolean, p_note text DEFAULT NULL::text)
 RETURNS admin_applications
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare a admin_applications; begin
  if not is_owner() then raise exception 'owner only'; end if;
  update admin_applications set status = case when p_approve then 'approved' else 'rejected' end, review_note = p_note, reviewed_by = auth.uid(), reviewed_at = now()
    where id = p_id and status = 'pending' returning * into a;
  if a.id is null then raise exception 'request not found'; end if;
  perform _audit(auth.uid(), case when p_approve then 'admin_application_approved' else 'admin_application_rejected' end, a.user_id, null, jsonb_build_object('application', a.id, 'note', p_note));
  perform _notify(a.user_id, 'admin_application', case when p_approve then 'درخواست ادمینی‌ات تأیید شد ✅' else 'درخواست ادمینی‌ات رد شد' end,
    case when p_approve then 'کد ادمین را از مالک بگیر و در «پنل ادمین» وارد کن.' else p_note end, jsonb_build_object('application', a.id));
  return a;
end $function$;

CREATE OR REPLACE FUNCTION public.owner_set_admin_status(p_user uuid, p_status text, p_note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not is_owner() then raise exception 'owner only'; end if;
  if p_status not in ('active','suspended','removed') then raise exception 'bad action'; end if;
  if is_owner(p_user) then raise exception 'not allowed'; end if;
  update admins set status = p_status, note = p_note, updated_at = now() where user_id = p_user;
  if not found then raise exception 'not admin'; end if;
  update profiles set role = case when p_status = 'removed' then 'player' else 'admin' end where id = p_user and role <> 'owner';
  perform _audit(auth.uid(), 'admin_' || p_status, p_user, null, jsonb_build_object('note', p_note));
  perform _notify(p_user, 'admin_status', case p_status when 'active' then 'ادمینی‌ات دوباره فعال شد' when 'suspended' then 'ادمینی‌ات موقتاً تعلیق شد' else 'دسترسی ادمین برداشته شد' end, p_note, '{}');
end $function$;

CREATE OR REPLACE FUNCTION public.player_tournament_history(p_user uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(jsonb_agg(x order by x->>'at' desc), '[]') from (
    select jsonb_build_object('tournament_id', t.id, 'name', t.name, 'status', t.status, 'format', t.format, 'mode', t.mode, 'team_name', e.team_name,
      'final_rank', e.final_rank, 'eliminated', e.eliminated, 'entries', (select count(*) from tournament_entries z where z.tournament_id = t.id and z.status = 'approved'),
      'gems', (select coalesce(sum(gems),0) from tournament_prizes pz where pz.tournament_id = t.id and pz.user_id = p_user),
      'wins', e.wins, 'losses', e.losses, 'draws', e.draws, 'at', coalesce(t.finished_at, t.starts_at, t.created_at)) x
    from tournament_entries e join tournaments t on t.id = e.tournament_id
    where p_user = any(e.members) and e.status = 'approved' order by coalesce(t.finished_at, t.starts_at, t.created_at) desc limit 50) q $function$;

CREATE OR REPLACE FUNCTION public.quick_match(p_mode text, p_kind text DEFAULT 'quick'::text)
 RETURNS rooms
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if p_kind not in ('quick','arena') then raise exception 'bad kind'; end if;
  return _matchmake(p_mode, p_kind, null); end $function$;

CREATE OR REPLACE FUNCTION public.redeem_admin_code(p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare app admin_applications; c admin_codes; h text; fails int; first_time boolean; bal int; begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  select count(*) into fails from admin_code_attempts where user_id = auth.uid() and not ok and at > now() - interval '1 hour';
  if fails >= 5 then return jsonb_build_object('ok', false, 'error', 'too many attempts'); end if;
  select * into app from admin_applications where user_id = auth.uid() and status = 'approved' order by created_at desc limit 1;
  if app.id is null then return jsonb_build_object('ok', false, 'error', 'no approved application'); end if;
  h := encode(extensions.digest(upper(regexp_replace(coalesce(p_code,''), '\s', '', 'g')), 'sha256'), 'hex');
  select * into c from admin_codes where code_hash = h and used_by is null and not revoked for update;
  if c.id is null then
    insert into admin_code_attempts(user_id, ok) values (auth.uid(), false);
    return jsonb_build_object('ok', false, 'error', 'invalid code', 'left', 4 - fails);
  end if;
  insert into admin_code_attempts(user_id, ok) values (auth.uid(), true);
  update admin_codes set used_by = auth.uid(), used_at = now() where id = c.id;
  first_time := not exists(select 1 from admin_bank_ledger where admin_id = auth.uid() and reason = 'admin_grant');
  insert into admins(user_id, status, granted_by, code_id, application_id) values (auth.uid(), 'active', app.reviewed_by, c.id, app.id)
    on conflict (user_id) do update set status = 'active', code_id = excluded.code_id, application_id = excluded.application_id, updated_at = now();
  update profiles set role = 'admin' where id = auth.uid() and role = 'player';
  update admin_applications set status = 'redeemed' where id = app.id;
  if first_time then bal := _bank(auth.uid(), 1000, 'admin_grant', null, 'بانک الماس ادمین'); else
    insert into admin_banks(admin_id) values (auth.uid()) on conflict do nothing; select balance into bal from admin_banks where admin_id = auth.uid(); end if;
  perform _audit(auth.uid(), 'admin_code_redeemed', auth.uid(), null, jsonb_build_object('code', c.id, 'bank_credit', case when first_time then 1000 else 0 end));
  perform _notify(auth.uid(), 'admin_granted', 'تو ادمین تورنمنت شدی! 🛡', 'بانک الماس ادمین: ' || bal, '{}');
  perform _notify_owners('admin_granted', 'ادمین جدید فعال شد', (select username from profiles where id = auth.uid()), jsonb_build_object('user', auth.uid()));
  return jsonb_build_object('ok', true, 'bank', bal, 'credited', first_time);
end $function$;

CREATE OR REPLACE FUNCTION public.register_tournament(p_tid uuid, p_team_name text DEFAULT NULL::text, p_code text DEFAULT NULL::text)
 RETURNS tournament_entries
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare t tournaments; e tournament_entries; n int; nm text; st text; begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  select * into t from tournaments where id = p_tid for update;
  if t.id is null then raise exception 'not found'; end if;
  if t.status not in ('registration','checkin') or (t.starts_at is not null and now() >= t.starts_at) then raise exception 'registration closed'; end if;
  if t.visibility = 'invite' and not _can_manage(p_tid) and not exists(select 1 from tournament_codes where tournament_id = p_tid and kind = 'tournament' and code = upper(trim(coalesce(p_code,'')))) then raise exception 'invite code required'; end if;
  perform _check_reqs(t, auth.uid());
  if t.prize_source = 'admin_bank' and t.created_by = auth.uid() then raise exception 'organizer cannot play'; end if;
  if exists(select 1 from tournament_entries where tournament_id = p_tid and auth.uid() = any(members) and status in ('pending','approved')) then raise exception 'already joined'; end if;
  delete from tournament_entries where tournament_id = p_tid and captain = auth.uid() and status in ('rejected','withdrawn','removed');
  select count(*) into n from tournament_entries where tournament_id = p_tid and status = 'approved';
  st := case when t.approval_required and not _can_manage(p_tid) then 'pending' else 'approved' end;
  if st = 'approved' and n >= t.max_entries then raise exception 'full'; end if;
  if st = 'pending' and (select count(*) from tournament_entries where tournament_id = p_tid and status = 'pending') >= t.max_entries * 2 then raise exception 'full'; end if;
  select username into nm from profiles where id = auth.uid();
  insert into tournament_entries(tournament_id, captain, team_name, members, status, checked_in)
    values (p_tid, auth.uid(), left(coalesce(nullif(trim(p_team_name),''), nm), 24), array[auth.uid()], st,
            case when t.status = 'checkin' then array[auth.uid()] else '{}'::uuid[] end) returning * into e;
  if _tsize(t.mode) > 1 then insert into tournament_codes(code, kind, tournament_id, entry_id) values (_code(6), 'entry', p_tid, e.id); end if;
  if st = 'pending' then perform _notify(t.created_by, 'registration_pending', 'ثبت‌نام جدید در انتظار تأیید', nm || ' · ' || t.name, jsonb_build_object('tournament', p_tid, 'entry', e.id)); end if;
  return e;
end $function$;

CREATE OR REPLACE FUNCTION public.report_match(p_match uuid, p_score_a integer, p_score_b integer, p_duration integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare m matches; r rooms; w smallint; u uuid; ra int; rb int; ex numeric; k int := 32; d int := 0; res int; my int; opp int; s record; prize int := 0; begin
  select * into m from matches where id=p_match for update;
  if m.id is null or m.status<>'live' then raise exception 'match not live'; end if;
  select * into r from rooms where id=m.room_id;
  if r.host<>auth.uid() then raise exception 'host only'; end if;
  if p_score_a<0 or p_score_b<0 or p_score_a>30 or p_score_b>30 then raise exception 'bad score'; end if;
  w := case when p_score_a>p_score_b then 0 when p_score_b>p_score_a then 1 else -1 end;
  if not m.bots then
    select avg(rating)::int into ra from profiles where id = any(m.team_a);
    select avg(rating)::int into rb from profiles where id = any(m.team_b);
    ex := 1/(1+power(10,(rb-ra)/400.0));
    d := coalesce(round(k*((case w when 0 then 1 when 1 then 0 else 0.5 end) - ex)), 0);
  end if;
  update matches set score_a=p_score_a, score_b=p_score_b, winner=w, status='done', ended_at=now(),
    duration_s=coalesce(p_duration, extract(epoch from now()-started_at)::int) where id=p_match;
  for u, res, my, opp in
    select x, case w when 0 then 1 when 1 then -1 else 0 end, p_score_a, p_score_b from unnest(m.team_a) x
    union all select x, case w when 1 then 1 when 0 then -1 else 0 end, p_score_b, p_score_a from unnest(m.team_b) x
  loop
    if m.bots then
      perform _grant(u, 15 + res*5 + my*2, 20 + (res=1)::int*20, 0, res, my, 'match_bots', p_match);
      continue;
    end if;
    perform _grant(u, 40 + res*30 + 10 + my*5, case when r.kind='duel' then 0 else 50 + (res=1)::int*100 end,
      case when m.ranked then (case when u = any(m.team_a) then d else -d end) else 0 end, res, my, 'match', p_match);
    update profiles set win_streak = case when res=1 then win_streak+1 else 0 end,
      best_streak = greatest(best_streak, case when res=1 then win_streak+1 else 0 end),
      arena_points = case when r.kind='arena' then greatest(0, arena_points + case res when 1 then 30 + least(win_streak,5)*5 when 0 then 5 else -20 end) else arena_points end
    where id=u;
    perform _progress(u,'play_online',1);
    perform _progress(u,'goals',my);
    if res=1 then perform _progress(u,'win_online',1); end if;
    if res=1 and r.kind='arena' then perform _progress(u,'win_arena',1); end if;
    if r.kind='quick' then perform _progress(u,'play_quick',1); end if;
    if r.kind='duel' then perform _progress(u,'play_duel',1); if res=1 then perform _progress(u,'win_duel',1); end if; end if;
    if res=1 and opp=0 then perform _progress(u,'clean_sheet',1); end if;
    if res=1 and my-opp >= 3 then perform _progress(u,'big_win',1); end if;
    if m.mode='2v2' then perform _progress(u,'play_2v2',1); elsif m.mode='3v3' then perform _progress(u,'play_3v3',1); end if;
    if m.tournament_match_id is not null then perform _progress(u,'play_tournament',1); end if;
    perform _progress(u,'streak',(select win_streak from profiles where id=u));
  end loop;
  if r.kind='duel' and not m.bots then
    if w = -1 then perform _refund_stakes(p_match);
    else
      for s in select st.*, t.prize as tprize from arena_stakes st join arena_tiers t on t.id=st.tier where st.match_id=p_match and st.status='held' for update of st loop
        if (w=0 and s.user_id = any(m.team_a)) or (w=1 and s.user_id = any(m.team_b)) then
          if s.currency='gems' then update profiles set gems=gems+s.tprize where id=s.user_id; else update profiles set coins=coins+s.tprize where id=s.user_id; end if;
          update arena_stakes set status='paid', prize=s.tprize, settled_at=now() where match_id=p_match and user_id=s.user_id;
          prize := s.tprize;
        else update arena_stakes set status='lost', settled_at=now() where match_id=p_match and user_id=s.user_id; end if;
      end loop;
    end if;
  end if;
  if m.tournament_match_id is not null then perform _tm_result(m.tournament_match_id, p_score_a, p_score_b); end if;
  update rooms set status='waiting', current_match=null, updated_at=now() where id=m.room_id;
  update room_players set ready=false where room_id=m.room_id;
  return jsonb_build_object('winner',w,'rating_delta',d,'prize',prize,'tier',r.tier,'bots',m.bots); end $function$;

CREATE OR REPLACE FUNCTION public.report_offline(p_won boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if p_won and (select count(*) from xp_events where user_id=auth.uid() and reason='offline' and created_at > now()-interval '2 minutes') = 0 then
    insert into xp_events(user_id,amount,reason) values (auth.uid(),10,'offline');
    update profiles set xp=xp+10, level=level_for_xp(xp+10) where id=auth.uid();
    perform _progress(auth.uid(),'win_bot',1);
  end if; end $function$;

CREATE OR REPLACE FUNCTION public.room_size(m text)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
AS $function$ select case m when '1v1' then 1 when '2v2' then 2 else 3 end $function$;

CREATE OR REPLACE FUNCTION public.set_ready(p_room uuid, p_ready boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin update room_players set ready=p_ready where room_id=p_room and user_id=auth.uid() and role='player';
  update rooms set updated_at=now() where id=p_room; end $function$;

CREATE OR REPLACE FUNCTION public.set_tournament_result(p_tm uuid, p_sa integer, p_sb integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare tm tournament_matches; begin select * into tm from tournament_matches where id=p_tm;
  if not exists(select 1 from tournaments where id=tm.tournament_id and created_by=auth.uid()) then raise exception 'organizer only'; end if;
  if tm.status not in ('ready','live') then raise exception 'not playable'; end if;
  perform _tm_result(p_tm, p_sa, p_sb); end $function$;

CREATE OR REPLACE FUNCTION public.spectate(p_room uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin update room_players set role='spectator', team=null, slot=null, ready=false where room_id=p_room and user_id=auth.uid(); end $function$;

CREATE OR REPLACE FUNCTION public.start_bot_match(p_room uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r rooms; begin
  select * into r from rooms where id=p_room for update;
  if r.id is null then raise exception 'room not found'; end if;
  if r.kind not in ('quick','arena') then raise exception 'not allowed'; end if;
  if r.status<>'waiting' then return r.current_match; end if;
  if not exists(select 1 from room_players where room_id=p_room and user_id=auth.uid() and role='player') then raise exception 'not allowed'; end if;
  if r.created_at > now() - interval '20 seconds' and (select count(*) from room_players where room_id=p_room and role='player') < room_size(r.mode)*2 then
    raise exception 'still searching'; end if;
  update room_players set ready=true where room_id=p_room and role='player';
  return _start_match(p_room, true);
end $function$;

CREATE OR REPLACE FUNCTION public.start_match(p_room uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r rooms; begin
  select * into r from rooms where id=p_room for update;
  if r.id is null then raise exception 'room not found'; end if;
  if r.status<>'waiting' then raise exception 'already started'; end if;
  if r.kind in ('quick','arena','duel') then
    if not exists(select 1 from room_players where room_id=p_room and user_id=auth.uid() and role='player') then raise exception 'not allowed'; end if;
    if exists(select 1 from room_players where room_id=p_room and role='player' and not ready) then raise exception 'not all ready'; end if;
    return _start_match(p_room, false);
  end if;
  if r.host<>auth.uid() then raise exception 'host only'; end if;
  if not exists(select 1 from room_players where room_id=p_room and user_id=auth.uid() and role='player') then raise exception 'take a seat'; end if;
  if exists(select 1 from room_players where room_id=p_room and role='player' and not ready and user_id<>r.host) then raise exception 'not all ready'; end if;
  return _start_match(p_room, true);
end $function$;

CREATE OR REPLACE FUNCTION public.start_tournament(p_tid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare t tournaments; ids uuid[]; n int; size int := 2; rounds int; r int; i int; mid uuid; nxt uuid; m record; begin
  select * into t from tournaments where id=p_tid for update;
  if t.created_by<>auth.uid() then raise exception 'organizer only'; end if;
  if t.status<>'registration' then raise exception 'already started'; end if;
  select array_agg(id order by random()) into ids from tournament_entries where tournament_id=p_tid;
  n := coalesce(array_length(ids,1),0);
  if n < 2 then raise exception 'need at least 2 entries'; end if;
  if t.format='double_elim' and n<=2 then update tournaments set format='single_elim' where id=p_tid; t.format:='single_elim'; end if;
  for i in 1..n loop update tournament_entries set seed=i where id=ids[i]; end loop;
  update tournaments set status='running', starts_at=coalesce(starts_at,now()) where id=p_tid;

  if t.format in ('round_robin','league') then
    perform _rr_schedule(p_tid, ids, case when t.format='league' then greatest(coalesce(t.rounds,2),1) else 1 end);
    update tournaments set current_round=1 where id=p_tid; return;
  elsif t.format='swiss' then
    update tournaments set rounds=coalesce(t.rounds, ceil(ln(n)/ln(2))::int) where id=p_tid;
    perform _swiss_round(p_tid, 1); return;
  end if;

  -- elimination brackets
  while size < n loop size := size*2; end loop;
  rounds := round(ln(size)/ln(2));
  for r in 1..rounds loop
    for i in 0..(size / (2^r)::int)-1 loop
      insert into tournament_matches(tournament_id,bracket,round,idx) values (p_tid, case when t.format='double_elim' then 'winners' else 'main' end, r, i);
    end loop;
  end loop;
  for m in select * from tournament_matches where tournament_id=p_tid and round<rounds loop
    select id into nxt from tournament_matches where tournament_id=p_tid and bracket=m.bracket and round=m.round+1 and idx=m.idx/2;
    update tournament_matches set next_match=nxt, next_slot=(m.idx%2) where id=m.id;
  end loop;
  if t.format='double_elim' then
    -- losers bracket: 2*(rounds-1) rounds, then grand final
    for r in 1..greatest(2*(rounds-1),0) loop
      for i in 0..greatest((size/(2^(((r+1)/2)+1))::int)-1,0) loop
        insert into tournament_matches(tournament_id,bracket,round,idx) values (p_tid,'losers',r,i);
      end loop;
    end loop;
    insert into tournament_matches(tournament_id,bracket,round,idx) values (p_tid,'final',1,0);
    -- wire losers bracket forward
    for m in select * from tournament_matches where tournament_id=p_tid and bracket='losers' loop
      if m.round = 2*(rounds-1) then select id into nxt from tournament_matches where tournament_id=p_tid and bracket='final';
        update tournament_matches set next_match=nxt, next_slot=1 where id=m.id;
      elsif m.round % 2 = 1 then select id into nxt from tournament_matches where tournament_id=p_tid and bracket='losers' and round=m.round+1 and idx=m.idx;
        update tournament_matches set next_match=nxt, next_slot=0 where id=m.id;
      else select id into nxt from tournament_matches where tournament_id=p_tid and bracket='losers' and round=m.round+1 and idx=m.idx/2;
        update tournament_matches set next_match=nxt, next_slot=(m.idx%2) where id=m.id; end if;
    end loop;
    -- winners bracket losers drop
    for m in select * from tournament_matches where tournament_id=p_tid and bracket='winners' loop
      if m.round=1 then select id into nxt from tournament_matches where tournament_id=p_tid and bracket='losers' and round=1 and idx=m.idx/2;
        update tournament_matches set loser_next=nxt, loser_slot=(m.idx%2) where id=m.id;
      elsif m.round=rounds then select id into nxt from tournament_matches where tournament_id=p_tid and bracket='final';
        update tournament_matches set next_match=nxt, next_slot=0 where id=m.id;
        select id into nxt from tournament_matches where tournament_id=p_tid and bracket='losers' and round=2*(rounds-1);
        update tournament_matches set loser_next=nxt, loser_slot=1 where id=m.id;
      else select id into nxt from tournament_matches where tournament_id=p_tid and bracket='losers' and round=2*(m.round-1) and idx=m.idx;
        update tournament_matches set loser_next=nxt, loser_slot=1 where id=m.id; end if;
    end loop;
  end if;
  -- seed round 1 (standard: entries 1..n, byes to top seeds)
  for i in 0..size/2-1 loop
    select id into mid from tournament_matches where tournament_id=p_tid and bracket in ('main','winners') and round=1 and idx=i;
    update tournament_matches set entry_a = ids[i*2+1], entry_b = case when i*2+2<=n then ids[i*2+2] end where id=mid;
  end loop;
  -- spread byes: if entry_b null -> auto-advance
  for m in select * from tournament_matches where tournament_id=p_tid and round=1 and bracket in ('main','winners') loop
    if m.entry_a is not null and m.entry_b is null then
      update tournament_matches set status='bye', winner_entry=m.entry_a where id=m.id;
      perform _tm_place(m.next_match, m.next_slot, m.entry_a);
    elsif m.entry_a is not null and m.entry_b is not null then update tournament_matches set status='ready' where id=m.id;
    elsif m.entry_a is null and m.entry_b is null then update tournament_matches set status='bye' where id=m.id;
    end if;
  end loop;
  perform _resolve_byes(p_tid);
  update tournaments set current_round=1 where id=p_tid;
end $function$;

CREATE OR REPLACE FUNCTION public.take_seat(p_room uuid, p_team smallint, p_slot smallint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r rooms; begin
  select * into r from rooms where id=p_room;
  if r.status<>'waiting' then raise exception 'match running'; end if;
  if p_slot<0 or p_slot>=room_size(r.mode) then raise exception 'bad slot'; end if;
  if exists(select 1 from room_players where room_id=p_room and team=p_team and slot=p_slot and role='player' and user_id<>auth.uid()) then raise exception 'seat taken'; end if;
  update room_players set role='player', team=p_team, slot=p_slot, ready=false where room_id=p_room and user_id=auth.uid();
  update rooms set updated_at=now() where id=p_room; end $function$;

CREATE OR REPLACE FUNCTION public.tournament_detail(p_tid uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare t tournaments; begin
  select * into t from tournaments where id = p_tid;
  if t.id is null then return null; end if;
  return jsonb_build_object(
    'tournament', to_jsonb(t),
    'organizer', (select jsonb_build_object('id', p.id, 'username', p.username, 'avatar', p.avatar, 'avatar_url', p.avatar_url, 'role', p.role,
        'admin', is_admin(p.id)) from profiles p where p.id = t.created_by),
    'entries', (select coalesce(jsonb_agg(jsonb_build_object('id', e.id, 'team_name', e.team_name, 'captain', e.captain, 'members', e.members, 'status', e.status,
        'seed', e.seed, 'group_no', e.group_no, 'points', e.points, 'played', e.played, 'wins', e.wins, 'draws', e.draws, 'losses', e.losses, 'gf', e.gf, 'ga', e.ga,
        'eliminated', e.eliminated, 'final_rank', e.final_rank, 'checked_in', coalesce(array_length(e.checked_in,1),0) > 0,
        'players', (select jsonb_agg(jsonb_build_object('id', p.id, 'username', p.username, 'avatar', p.avatar, 'avatar_url', p.avatar_url, 'level', p.level, 'rating', p.rating))
           from profiles p where p.id = any(e.members))) order by e.seed nulls last, e.created_at), '[]')
      from tournament_entries e where e.tournament_id = p_tid and (e.status in ('approved') or _can_manage(p_tid) or auth.uid() = any(e.members))),
    'matches', (select coalesce(jsonb_agg(to_jsonb(m) order by m.bracket, m.round, m.idx), '[]') from tournament_matches m where m.tournament_id = p_tid),
    'my_entry', (select to_jsonb(e) from tournament_entries e where e.tournament_id = p_tid and auth.uid() = any(e.members) and e.status in ('pending','approved') limit 1),
    'my_team_code', (select c.code from tournament_codes c join tournament_entries e on e.id = c.entry_id where c.tournament_id = p_tid and auth.uid() = any(e.members) limit 1),
    'invite_code', (select c.code from tournament_codes c where c.tournament_id = p_tid and c.kind = 'tournament' and (
        _can_manage(p_tid) or exists(select 1 from tournament_entries e where e.tournament_id = p_tid and auth.uid() = any(e.members) and e.status in ('pending','approved')))),
    'can_manage', _can_manage(p_tid),
    'counts', jsonb_build_object('approved', (select count(*) from tournament_entries where tournament_id = p_tid and status = 'approved'),
                                 'pending', (select count(*) from tournament_entries where tournament_id = p_tid and status = 'pending')),
    'prizes', (select coalesce(jsonb_agg(jsonb_build_object('user_id', x.user_id, 'place', x.place, 'gems', x.gems)), '[]') from tournament_prizes x where x.tournament_id = p_tid),
    'now', now());
end $function$;

CREATE OR REPLACE FUNCTION public.tournament_tick()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare t record; m record; pa boolean; pb boolean; begin
  perform pg_advisory_xact_lock(hashtext('nexora-tour-tick'));
  for t in select * from tournaments where v = 2 and status = 'registration' and check_in_minutes > 0 and now() >= starts_at - make_interval(mins => check_in_minutes) and now() < starts_at loop
    update tournaments set status = 'checkin' where id = t.id;
    perform _notify_entries(t.id, 'checkin_open', 'Check-in «' || t.name || '» باز شد ✅', 'تا ' || to_char(t.starts_at at time zone 'Asia/Tehran','HH24:MI') || ' تهران اعلام حضور کن وگرنه حذف می‌شوی');
  end loop;
  for t in select * from tournaments where v = 2 and status in ('registration','checkin') and not reminded and now() >= starts_at - interval '15 minutes' and now() < starts_at loop
    update tournaments set reminded = true where id = t.id;
    perform _notify_entries(t.id, 'tournament_soon', '«' || t.name || '» تا ۱۵ دقیقه‌ی دیگر شروع می‌شود ⏰', null);
  end loop;
  for t in select id from tournaments where v = 2 and status in ('registration','checkin') and now() >= starts_at loop perform _v6_start(t.id); end loop;
  -- overdue matches: walkover for the side that showed up in the room, otherwise ask the organizer
  for m in select tm.* from tournament_matches tm join tournaments tt on tt.id = tm.tournament_id
     where tt.v = 2 and tt.status = 'running' and tm.status = 'ready' and tm.deadline < now() loop
    select exists(select 1 from room_players rp, tournament_entries e where rp.room_id = m.room_id and e.id = m.entry_a and rp.user_id = any(e.members)),
           exists(select 1 from room_players rp, tournament_entries e where rp.room_id = m.room_id and e.id = m.entry_b and rp.user_id = any(e.members)) into pa, pb;
    if pa and not pb then perform _tm_result(m.id, 3, 0); perform _audit(null, 'walkover', null, m.tournament_id, jsonb_build_object('match', m.id, 'winner', 'a'));
    elsif pb and not pa then perform _tm_result(m.id, 0, 3); perform _audit(null, 'walkover', null, m.tournament_id, jsonb_build_object('match', m.id, 'winner', 'b'));
    else
      update tournament_matches set deadline = now() + interval '15 minutes' where id = m.id;
      perform _notify((select created_by from tournaments where id = m.tournament_id), 'match_overdue', 'یک مسابقه‌ی تورنمنت دیر شده', 'نتیجه را در پنل ادمین ثبت کن', jsonb_build_object('tournament', m.tournament_id, 'match', m.id));
    end if;
  end loop;
end $function$;

CREATE OR REPLACE FUNCTION public.transfer_host(p_room uuid, p_user uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not exists(select 1 from rooms where id=p_room and host=auth.uid()) then raise exception 'host only'; end if;
  if not exists(select 1 from room_players where room_id=p_room and user_id=p_user) then raise exception 'not in room'; end if;
  update rooms set host=p_user, updated_at=now() where id=p_room; end $function$;

CREATE OR REPLACE FUNCTION public.update_club(p_club uuid, p_desc text, p_policy text, p_emblem text, p_min_level integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin if _club_role(p_club) <> 'leader' then raise exception 'leader only'; end if;
  update clubs set description=coalesce(p_desc,description), join_policy=coalesce(p_policy,join_policy), emblem=coalesce(p_emblem,emblem),
    min_level=coalesce(p_min_level,min_level) where id=p_club; end $function$;

CREATE OR REPLACE FUNCTION public.update_conversation(p_conv uuid, p_title text, p_about text, p_avatar_url text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not exists(select 1 from conversation_members where conversation_id=p_conv and user_id=auth.uid() and role in ('owner','admin')) then raise exception 'admin only'; end if;
  update conversations set title=coalesce(nullif(trim(p_title),''),title), about=coalesce(p_about,about), avatar_url=coalesce(p_avatar_url,avatar_url) where id=p_conv; end $function$;

CREATE OR REPLACE FUNCTION public.update_room(p_room uuid, p_settings jsonb, p_name text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin update rooms set settings=coalesce(p_settings,settings), name=coalesce(nullif(trim(p_name),''),name), updated_at=now()
  where id=p_room and host=auth.uid() and status='waiting' and kind in ('casual','social') and tournament_match_id is null; end $function$;

CREATE OR REPLACE FUNCTION public.update_room_meta(p_room uuid, p_private boolean DEFAULT NULL::boolean, p_voice boolean DEFAULT NULL::boolean, p_ranked boolean DEFAULT NULL::boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not exists(select 1 from rooms where id=p_room and host=auth.uid() and status='waiting' and kind in ('casual','social')) then raise exception 'host only'; end if;
  update rooms set is_private=coalesce(p_private,is_private), voice=coalesce(p_voice,voice),
    ranked=case when kind='social' then false else coalesce(p_ranked,ranked) end, updated_at=now() where id=p_room; end $function$;

CREATE OR REPLACE FUNCTION public.update_tournament_v2(p_tid uuid, p jsonb)
 RETURNS tournaments
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare t tournaments; pool jsonb; d int; n int; begin
  select * into t from tournaments where id = p_tid for update;
  if t.id is null then raise exception 'not found'; end if;
  if not _can_manage(p_tid) then raise exception 'organizer only'; end if;
  if t.status not in ('registration','checkin') then raise exception 'already started'; end if;
  if p ? 'prize_pool' then
    pool := _v6_pool(p->'prize_pool'); d := _pool_sum(pool) - t.prize_escrow;
    if t.prize_source = 'none' and _pool_sum(pool) > 0 then
      if not is_admin() then raise exception 'admin only'; end if;
      t.prize_source := case when is_owner() then 'system' else 'admin_bank' end;
    end if;
    if t.prize_source = 'admin_bank' and d <> 0 then perform _bank(t.created_by, -d, case when d > 0 then 'prize_escrow' else 'prize_refund' end, t.id, 'ویرایش جایزه'); end if;
    update tournaments set prize_pool = pool, prize_escrow = case when t.prize_source = 'admin_bank' then _pool_sum(pool) else 0 end,
      prize_source = t.prize_source, prize_gems = coalesce((pool->>0)::int, 0) where id = p_tid;
  end if;
  if p ? 'max_entries' then
    select count(*) into n from tournament_entries where tournament_id = p_tid and status = 'approved';
    if (p->>'max_entries')::int < greatest(n,2) or (p->>'max_entries')::int > 64 then raise exception 'bad size'; end if;
  end if;
  if p ? 'starts_at' and ((p->>'starts_at')::timestamptz < now() + interval '1 minute') then raise exception 'bad start time'; end if;
  update tournaments set
    name = coalesce(nullif(trim(p->>'name'),''), name), description = case when p ? 'description' then nullif(trim(p->>'description'),'') else description end,
    rules = case when p ? 'rules' then _v6_rules(p->'rules') else rules end, style = coalesce(p->'style', style),
    starts_at = coalesce((p->>'starts_at')::timestamptz, starts_at), reminded = case when p ? 'starts_at' then false else reminded end,
    check_in_minutes = coalesce(least(180, greatest(0, (p->>'check_in_minutes')::int)), check_in_minutes),
    approval_required = coalesce((p->>'approval_required')::boolean, approval_required), visibility = coalesce(nullif(p->>'visibility',''), visibility),
    requirements = coalesce(p->'requirements', requirements), min_level = coalesce(greatest(1,(p#>>'{requirements,min_level}')::int), min_level),
    max_entries = coalesce((p->>'max_entries')::int, max_entries),
    status = case when p ? 'starts_at' then 'registration' else status end
  where id = p_tid returning * into t;
  perform _audit(auth.uid(), 'tournament_update', null, p_tid, p);
  return t;
end $function$;

CREATE OR REPLACE FUNCTION public.username_available(p_name text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ select char_length(trim(p_name)) between 3 and 20 and not exists(select 1 from profiles where lower(username)=lower(trim(p_name))) $function$;

CREATE OR REPLACE FUNCTION public.wc_tick()
 RETURNS tournaments
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare m date := date_trunc('month', now() at time zone 'Asia/Tehran')::date; t tournaments; x record;
  mon text[] := array['فروردین','اردیبهشت','خرداد','تیر','مرداد','شهریور','مهر','آبان','آذر','دی','بهمن','اسفند']; begin
  perform pg_advisory_xact_lock(hashtext('nexora-wc'));
  insert into tournaments(name,format,mode,max_entries,status,created_by,prize_xp,prize_coins,prize_gems,starts_at,month,stage)
  values ('جام جهانی NEXORA · '||to_char(m,'YYYY-MM'),'world_cup','1v1',64,'registration',null,0,0,500,
          (m + 24)::timestamp at time zone 'Asia/Tehran', m, 'qualifying')
  on conflict do nothing;
  select * into t from tournaments where format='world_cup' and month=m;
  if t.status='registration' and now() >= t.starts_at then perform _wc_seed(t.id); end if;
  -- every playable cup match gets a deadline; overdue ones are decided (group: 0-0, knockout: higher seed advances)
  update tournament_matches tm set deadline=now()+interval '2 days' from tournaments tt
    where tt.id=tm.tournament_id and tt.format='world_cup' and tm.status='ready' and tm.deadline is null;
  for x in select tm.id from tournament_matches tm join tournaments tt on tt.id=tm.tournament_id
     where tt.format='world_cup' and tt.status='running' and tm.status in ('ready','live') and tm.deadline < now() - case when tm.status='live' then interval '1 hour' else interval '0' end
     order by tm.bracket desc, tm.round, tm.idx loop
    if exists(select 1 from tournament_matches where id=x.id and status in ('ready','live')) then
      update tournament_matches set status='ready' where id=x.id;
      perform _tm_result(x.id, 0, 0);
    end if;
  end loop;
  select * into t from tournaments where format='world_cup' and month=m;
  return t; end $function$;

CREATE OR REPLACE FUNCTION public.xp_for_level(l integer)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
AS $function$ select ((greatest(l,1)-1)*(greatest(l,1)-1)*100) $function$;


-- ===== TRIGGERS =====
CREATE TRIGGER ch_club AFTER INSERT ON public.club_members FOR EACH ROW EXECUTE FUNCTION _ch_club();
CREATE TRIGGER ch_follow AFTER INSERT ON public.follows FOR EACH ROW EXECUTE FUNCTION _ch_follow();
CREATE TRIGGER ch_clubmatch AFTER UPDATE OF status ON public.matches FOR EACH ROW EXECUTE FUNCTION _ch_clubmatch();
CREATE TRIGGER ch_message AFTER INSERT ON public.messages FOR EACH ROW EXECUTE FUNCTION _ch_message();
CREATE TRIGGER msg_touch AFTER INSERT ON public.messages FOR EACH ROW EXECUTE FUNCTION _touch_conv();
CREATE TRIGGER trg_room_default_field BEFORE INSERT ON public.rooms FOR EACH ROW EXECUTE FUNCTION _room_default_field();
-- auth: CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION handle_new_user();
-- auth: CREATE TRIGGER on_auth_user_updated AFTER UPDATE OF is_anonymous ON auth.users FOR EACH ROW EXECUTE FUNCTION handle_user_upgrade();
-- auth: CREATE TRIGGER zz_nexora_owner AFTER INSERT OR UPDATE OF email, email_confirmed_at ON auth.users FOR EACH ROW EXECUTE FUNCTION _sync_owner();

-- ===== RLS POLICIES =====
create policy "own or owner" on public.admin_applications as permissive for select to public
  using (((user_id = auth.uid()) OR is_owner()));
create policy "owner or actor" on public.admin_audit as permissive for select to public
  using ((is_owner() OR (actor = auth.uid())));
create policy "own or owner" on public.admin_bank_ledger as permissive for select to public
  using (((admin_id = auth.uid()) OR is_owner()));
create policy "own or owner" on public.admin_banks as permissive for select to public
  using (((admin_id = auth.uid()) OR is_owner()));
create policy "read" on public.admins as permissive for select to public
  using (true);
create policy "read own" on public.arena_stakes as permissive for select to authenticated
  using ((user_id = auth.uid()));
create policy "read" on public.arena_tiers as permissive for select to public
  using (true);
create policy "read" on public.challenge_defs as permissive for select to public
  using (true);
create policy "read" on public.club_challenges as permissive for select to authenticated
  using ((EXISTS ( SELECT 1
   FROM club_members m
  WHERE ((m.user_id = auth.uid()) AND (m.club_id = ANY (ARRAY[club_challenges.from_club, club_challenges.to_club]))))));
create policy "read" on public.club_members as permissive for select to authenticated
  using (true);
create policy "read" on public.club_requests as permissive for select to authenticated
  using (((user_id = auth.uid()) OR (EXISTS ( SELECT 1
   FROM club_members cm
  WHERE ((cm.club_id = club_requests.club_id) AND (cm.user_id = auth.uid()) AND (cm.role = ANY (ARRAY['leader'::text, 'officer'::text])))))));
create policy "read" on public.clubs as permissive for select to authenticated
  using (true);
create policy "read" on public.conversation_members as permissive for select to authenticated
  using ((is_member(conversation_id) OR (EXISTS ( SELECT 1
   FROM conversations v
  WHERE ((v.id = conversation_members.conversation_id) AND v.is_public)))));
create policy "update self" on public.conversation_members as permissive for update to authenticated
  using ((user_id = auth.uid()))
  with check ((user_id = auth.uid()));
create policy "read" on public.conversations as permissive for select to authenticated
  using ((is_public OR is_member(id)));
create policy "read" on public.disc_packs as permissive for select to public
  using (true);
create policy "read" on public.discs as permissive for select to public
  using (true);
create policy "follow" on public.follows as permissive for insert to authenticated
  with check ((follower = auth.uid()));
create policy "read" on public.follows as permissive for select to authenticated
  using (true);
create policy "unfollow" on public.follows as permissive for delete to authenticated
  using ((follower = auth.uid()));
create policy "read" on public.inventory as permissive for select to authenticated
  using (true);
create policy "read" on public.leagues as permissive for select to public
  using (true);
create policy "read" on public.matches as permissive for select to authenticated
  using (true);
create policy "delete own" on public.messages as permissive for update to authenticated
  using ((sender = auth.uid()))
  with check ((sender = auth.uid()));
create policy "read" on public.messages as permissive for select to authenticated
  using ((is_member(conversation_id) OR (EXISTS ( SELECT 1
   FROM conversations v
  WHERE ((v.id = messages.conversation_id) AND v.is_public AND (v.kind = 'channel'::text))))));
create policy "send" on public.messages as permissive for insert to authenticated
  with check (((sender = auth.uid()) AND can_post(conversation_id)));
create policy "own delete" on public.notifications as permissive for delete to public
  using ((user_id = auth.uid()));
create policy "own read" on public.notifications as permissive for select to public
  using ((user_id = auth.uid()));
create policy "own update" on public.notifications as permissive for update to public
  using ((user_id = auth.uid()))
  with check ((user_id = auth.uid()));
create policy "read" on public.profiles as permissive for select to authenticated
  using (true);
create policy "update self" on public.profiles as permissive for update to authenticated
  using ((id = auth.uid()))
  with check ((id = auth.uid()));
create policy "read" on public.room_players as permissive for select to authenticated
  using (true);
create policy "read" on public.rooms as permissive for select to authenticated
  using (((NOT is_private) OR (EXISTS ( SELECT 1
   FROM room_players p
  WHERE ((p.room_id = rooms.id) AND (p.user_id = auth.uid())))) OR (host = auth.uid())));
create policy "read own" on public.season_claims as permissive for select to authenticated
  using ((user_id = auth.uid()));
create policy "read" on public.season_rewards as permissive for select to public
  using (true);
create policy "read" on public.seasons as permissive for select to public
  using (true);
create policy "managers or members" on public.tournament_codes as permissive for select to public
  using ((_can_manage(tournament_id) OR ((kind = 'entry'::text) AND (EXISTS ( SELECT 1
   FROM tournament_entries e
  WHERE ((e.id = tournament_codes.entry_id) AND (auth.uid() = ANY (e.members)))))) OR ((kind = 'tournament'::text) AND (EXISTS ( SELECT 1
   FROM tournament_entries e
  WHERE ((e.tournament_id = tournament_codes.tournament_id) AND (auth.uid() = ANY (e.members)) AND (e.status = ANY (ARRAY['pending'::text, 'approved'::text]))))))));
create policy "read" on public.tournament_entries as permissive for select to authenticated
  using (true);
create policy "read" on public.tournament_matches as permissive for select to authenticated
  using (true);
create policy "read" on public.tournament_prizes as permissive for select to public
  using (true);
create policy "read" on public.tournaments as permissive for select to authenticated
  using (true);
create policy "own" on public.user_blocks as permissive for all to authenticated
  using ((blocker = auth.uid()))
  with check ((blocker = auth.uid()));
create policy "read own" on public.user_challenges as permissive for select to authenticated
  using ((user_id = auth.uid()));
create policy "read own" on public.xp_events as permissive for select to authenticated
  using ((user_id = auth.uid()));

