-- ===== CRON =====
-- cron nexora-sweep [* * * * *]: select public._sweep_rooms()
-- cron nexora-worldcup [7 * * * *]: select public.wc_tick()
-- cron nexora-cleanup [17 3 * * *]: select public._daily_cleanup()
-- cron nexora-tournaments [* * * * *]: select public.tournament_tick()
